// Request flows for a specific event (admin schedule page)
socket.on('requestEventFlows', async ({ eventId: reqEventId }) => {
  if (!reqEventId) return;
  const flows = await prisma.depFlow.findMany({ where: { eventId: reqEventId } });
  const rates = {};
  const types = {};
  for (const f of flows) {
    rates[f.sector] = Number(f.rate) || 0;
    const ft = (f.flowtype || 'NONE').toString().toUpperCase();
    types[f.sector] = (ft === 'SLOTTED' || ft === 'BOOKING_ONLY' || ft === 'NONE') ? ft : 'NONE';
  }
  socket.emit('syncDepFlows', rates);
  socket.emit('syncFlowTypes', types);
});

socket.on('updateDepFlow', async ({ sector, value, eventId: clientEventId }) => {
  const key = normalizeSectorKey(sector);
  const rate = Number(value);
  const evtId = clientEventId || activeEventId || 0;
  const isActiveEvent = evtId === activeEventId;

  // treat blank / 0 / invalid as "remove rate"
  if (!Number.isFinite(rate) || rate <= 0) {
    if (isActiveEvent) delete sharedDepFlows[key];

    await prisma.depFlow.deleteMany({ where: { eventId: evtId, sector: key } });

    io.emit('depFlowUpdated', { sector: key, value: 0, eventId: evtId });
    if (isActiveEvent) {
      rebuildAllTobtSlots();
      const fromIcao = key.split('-')[0];
      io.to(`icao:${fromIcao}`).emit(
        'unassignedTobtUpdate',
        buildUnassignedTobtsForICAO(fromIcao)
      );
    }

    return;
  }

  if (isActiveEvent) sharedDepFlows[key] = rate;

  await prisma.depFlow.upsert({
    where: { eventId_sector: { eventId: evtId, sector: key } },
    update: { rate },
    create: {
      eventId: evtId,
      sector: key,
      rate,
      flowtype: (isActiveEvent ? sharedFlowTypes[key] : null) || 'NONE'
    }
  });

  io.emit('depFlowUpdated', { sector: key, value: rate, eventId: evtId });
  if (isActiveEvent) {
    rebuildAllTobtSlots();
    const fromIcao = key.split('-')[0];
    io.to(`icao:${fromIcao}`).emit(
      'unassignedTobtUpdate',
      buildUnassignedTobtsForICAO(fromIcao)
    );
  }
});

socket.on('updateDepFlowType', async ({ sector, flowtype, eventId: clientEventId }) => {
  const key = normalizeSectorKey(sector);
  const evtId = clientEventId || activeEventId || 0;
  const isActiveEvent = evtId === activeEventId;

  const ft = (flowtype || 'NONE').toString().toUpperCase();
  const normalized =
    ft === 'SLOTTED' || ft === 'BOOKING_ONLY' || ft === 'NONE'
      ? ft
      : 'NONE';

  if (isActiveEvent) sharedFlowTypes[key] = normalized;

  await prisma.depFlow.upsert({
    where: { eventId_sector: { eventId: evtId, sector: key } },
    update: { flowtype: normalized },
    create: {
      eventId: evtId,
      sector: key,
      rate: (isActiveEvent ? sharedDepFlows[key] : null) || 0,
      flowtype: normalized
    }
  });

  io.emit('depFlowTypeUpdated', { sector: key, flowtype: normalized, eventId: evtId });

  if (isActiveEvent && (normalized === 'SLOTTED' || normalized === 'BOOKING_ONLY')) {
    autoAssignTeamThenAffiliate({ reason: `flow ${normalized} set for ${key}` }).catch(() => {});
  }
});

socket.on('createBookingOnly', async ({ sector, callsign: enteredCid, teamBooking, teamCallsign }) => {

  console.log('[BOOKING ONLY]', sector, enteredCid, teamBooking ? '(team)' : '');

  if (!sector || !enteredCid) return;
  if (!user || !user.cid) return;

  const sessionCid = Number(user.cid);

  // Resolve which CID this booking is filed under.
  // Team booking: viewer must be a WF_TEAM member whose linked team is
  // participating and whose mainCid matches enteredCid. Book under that CID.
  // Otherwise: book under the session CID (enteredCid is a confirmation).
  let bookingCid = sessionCid;
  if (teamBooking) {
    if (!isTeamMember(sessionCid)) {
      socket.emit('bookingError', { error: 'Not a team member.' });
      return;
    }
    const wfTeamRow = await prisma.userAdditionalRole.findUnique({
      where: { cid_role: { cid: sessionCid, role: 'WF_TEAM' } }
    }).catch(() => null);
    if (!wfTeamRow?.teamName) {
      socket.emit('bookingError', { error: 'Your team is not linked.' });
      return;
    }
    const allTeams = await prisma.officialTeam.findMany({
      select: { teamName: true, mainCid: true, participatingWf26: true }
    });
    const match = allTeams.find(t =>
      String(t.teamName || '').trim().toUpperCase() === wfTeamRow.teamName &&
      t.participatingWf26 &&
      Number(t.mainCid) === Number(enteredCid)
    );
    if (!match) {
      socket.emit('bookingError', { error: 'Team owner CID mismatch or team not participating.' });
      return;
    }
    bookingCid = Number(enteredCid);
  }

  const [leg, dateUtc, depTimeUtc] = sector.split('|');
  if (!leg || !dateUtc || !depTimeUtc) return;

  const [from, to] = leg.split('-');

  const row = adminSheetCache.find(
    r =>
      r.from === from &&
      r.to === to &&
      r.date_utc === dateUtc &&
      r.dep_time_utc === depTimeUtc
  );
  if (!row) return;

  const slotKey =
    `${from}-${to}|${row.date_utc}|${row.dep_time_utc}|BOOKING_ONLY`;

  // Check capacity
  const capacity = getBookingOnlyCapacity(from, to);
  if (capacity.total > 0 && capacity.remaining <= 0) {
    socket.emit('bookingError', { error: 'No remaining bookings for this sector' });
    return;
  }

  // Prevent duplicate per booking CID
  const userBookingKey = `${bookingCid}:${slotKey}`;
  if (tobtBookingsByKey[userBookingKey]) {
    socket.emit('bookingError', { error: 'There is already a booking for this sector under that CID.' });
    return;
  }

  // For team bookings, resolve the team's actual callsign
  let bookingCallsign = String(bookingCid);
  if (teamBooking) {
    const bookerTeamRow = await prisma.userAdditionalRole.findUnique({
      where: { cid_role: { cid: sessionCid, role: 'WF_TEAM' } }
    }).catch(() => null);
    if (bookerTeamRow?.teamName) {
      const allTeamCs = await prisma.officialTeam.findMany({
        where: { participatingWf26: true },
        select: { teamName: true, callsign: true }
      }).catch(() => []);
      const myTeamCs = allTeamCs
        .filter(t => String(t.teamName || '').trim().toUpperCase() === bookerTeamRow.teamName)
        .map(t => String(t.callsign || '').toUpperCase());
      if (teamCallsign && myTeamCs.includes(String(teamCallsign).toUpperCase())) {
        bookingCallsign = String(teamCallsign).toUpperCase();
      } else if (myTeamCs.length > 0) {
        bookingCallsign = myTeamCs[0];
      }
    }
  }

  // Determine route assignment (A = primary, B = secondary)
  // WF teams and affiliates always get Route A (primary)
  let assignedRoute = 'A';
  const isTeamOrAffiliate = isTeamMember(bookingCid) || isAffiliate(bookingCid);
  if (!isTeamOrAffiliate) {
    // Check if there's an agreed split for this sector
    const sectorPlan = await prisma.sectorPlan.findFirst({
      where: { wf: row.number, eventId: activeEventId || undefined }
    }).catch(() => null);
    if (sectorPlan?.splitAgreed && sectorPlan.depSplitRoute && sectorPlan.depSplitPct != null) {
      const splitPct = sectorPlan.depSplitPct; // % on Route A
      // Count existing Route A vs B bookings for this sector
      const sectorPrefix = `${from}-${to}|`;
      let countA = 0, countB = 0;
      for (const [k, b] of Object.entries(tobtBookingsByKey)) {
        if (k.includes(':') && b.slotKey?.startsWith(sectorPrefix)) {
          if (b.assignedRoute === 'B') countB++;
          else countA++;
        }
      }
      const total = countA + countB;
      // Assign to whichever route is furthest below its target ratio
      const targetA = splitPct / 100;
      const currentRatioA = total > 0 ? countA / total : 1;
      assignedRoute = currentRatioA > targetA ? 'B' : 'A';
    }
  }

  await prisma.tobtBooking.create({
    data: {
      slotKey,
      cid: bookingCid,
      callsign: bookingCallsign,
      from,
      to,
      dateUtc: row.date_utc,
      depTimeUtc: row.dep_time_utc,
      tobtTimeUtc: null,
      assignedRoute
    }
  });

  const bookingData = {
    slotKey,
    cid: bookingCid,
    callsign: bookingCallsign,
    from,
    to,
    dateUtc: row.date_utc,
    depTimeUtc: row.dep_time_utc,
    tobtTimeUtc: null,
    assignedRoute,
    createdAtISO: new Date().toISOString()
  };

  const bookingKey = `${bookingCid}:${slotKey}`;
  setBooking(bookingData);

  if (!tobtBookingsByCid[bookingCid]) {
    tobtBookingsByCid[bookingCid] = new Set();
  }
  tobtBookingsByCid[bookingCid].add(bookingKey);

  io.emit('bookingCreated', { slotKey, assignedRoute });
  vatcanPushForSlotKey(slotKey);
});



