// FIR Events Access — admin grants per-user access to specific FIRs or entire
// divisions. Used by the Sector Planning page to compute which WF sectors a
// user is "participating in" (dep airport, arr airport, or enroute FIR).
app.get('/admin/api/fir-events-access/:cid', requireAdmin, async (req, res) => {
  const cid = Number(req.params.cid);
  if (!cid) return res.status(400).json({ error: 'cid required' });
  try {
    const rows = await prisma.firEventAccess.findMany({
      where: { cid },
      orderBy: [{ scope: 'asc' }, { value: 'asc' }]
    });
    // FIRs auto-granted via the WF FIR Management spreadsheet (not revocable
    // here — managed on the sheet itself, resynced hourly).
    const csv = firManagementState.data?.cidToFirs;
    const autoFirs = (csv && (csv[cid] || csv[String(cid)])) || [];
    res.json({ cid, grants: rows, autoFirs: [...autoFirs] });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/admin/api/fir-events-access', requireAdmin, async (req, res) => {
  const cid = Number(req.body?.cid);
  const scope = String(req.body?.scope || '').toUpperCase();
  const value = String(req.body?.value || '').trim().toUpperCase();
  const grantedBy = Number(req.session?.user?.data?.cid) || null;
  if (!cid || !value) return res.status(400).json({ error: 'cid and value required' });
  if (scope !== 'FIR' && scope !== 'DIVISION') return res.status(400).json({ error: 'scope must be FIR or DIVISION' });
  try {
    const row = await prisma.firEventAccess.upsert({
      where: { cid_scope_value: { cid, scope, value } },
      update: {},
      create: { cid, scope, value, createdBy: grantedBy }
    });
    firAccessCids.add(cid);
    res.json({ success: true, grant: row });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.delete('/admin/api/fir-events-access/:id', requireAdmin, async (req, res) => {
  try {
    await prisma.firEventAccess.delete({ where: { id: Number(req.params.id) } });
    await loadFirAccessCids();
    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── Admin impersonation: browse the site as another user ──
// The real admin session is parked in req.session.impersonatorUser and a
// minimal session user is built for the target CID (same shape as the
// dev-login custom-CID path). The layout shows a banner whenever
// user._impersonation is set; POST /impersonate/stop restores the admin.
app.post('/admin/api/impersonate', requireAdmin, async (req, res) => {
  const targetCid = Number(req.body?.cid);
  if (!targetCid || targetCid <= 0) return res.status(400).json({ error: 'cid required' });
  if (req.session.impersonatorUser) return res.status(400).json({ error: 'Already viewing as another user — return to normal view first' });
  const selfCid = Number(req.session.user?.data?.cid);
  if (targetCid === selfCid) return res.status(400).json({ error: 'That is already you' });

  let displayName = `User ${targetCid}`;
  try {
    const u = await prisma.user.findUnique({ where: { cid: targetCid }, select: { name: true } });
    if (u?.name) displayName = u.name;
  } catch {}
  const parts = displayName.trim().split(/\s+/);

  req.session.impersonatorUser = req.session.user;
  req.session.user = { data: {
    cid: targetCid,
    personal: {
      name_first: parts[0] || displayName,
      name_last: parts.slice(1).join(' '),
      name_full: displayName
    },
    vatsim: {
      rating: { id: 1, short: 'OBS', long: 'Observer' },
      pilotrating: { id: 0, short: 'NEW', long: 'Basic Member' },
      division: { id: '', name: '' },
      region: { id: '', name: '' }
    },
    oauth: { token_valid: true },
    _impersonation: { byCid: selfCid }
  } };
  req.session.save(() => res.json({ success: true, cid: targetCid, name: displayName }));
});

app.post('/impersonate/stop', (req, res) => {
  if (!req.session.impersonatorUser) return res.redirect('/');
  req.session.user = req.session.impersonatorUser;
  delete req.session.impersonatorUser;
  req.session.save(() => res.redirect('/admin/access-management'));
});

