app.post('/admin/api/user-additional-roles/toggle', requireAdmin, async (req, res) => {
  const cid = Number(req.body?.cid);
  const role = String(req.body?.role || '');
  const enabled = !!req.body?.enabled;
  const teamName = req.body?.teamName ? String(req.body.teamName).trim().toUpperCase() : null;
  const affiliateId = Number(req.body?.affiliateId) || null;
  if (!cid) return res.status(400).json({ error: 'CID required' });
  if (!USER_ADDITIONAL_ROLES.includes(role)) return res.status(400).json({ error: 'Invalid role' });
  if (role === 'WF_TEAM' && enabled && !teamName) {
    return res.status(400).json({ error: 'teamName required for WF_TEAM' });
  }

  if (enabled) {
    const data = role === 'WF_TEAM' ? { teamName } : { teamName: null };
    await prisma.userAdditionalRole.upsert({
      where: { cid_role: { cid, role } },
      update: data,
      create: { cid, role, ...data }
    });
    if (role === 'WF_TEAM') teamMemberCids.add(cid);
    if (role === 'WF_AFFILIATE') affiliateCids.add(cid);
    if (role === 'WF_ATC') wfAtcCids.add(cid);

    // Tagging WF Affiliate with an affiliate picked means MEMBERSHIP of that
    // affiliate, not ownership — the main CID is never touched here (transfers
    // live on the Official Teams admin page, which also moves bookings).
    // The membership row is what puts them in the Discord roster.
    if (role === 'WF_AFFILIATE' && affiliateId) {
      const aff = await prisma.affiliate.findUnique({ where: { id: affiliateId } }).catch(() => null);
      if (!aff) return res.status(404).json({ error: 'Affiliate not found' });
      if (Number(aff.cid) !== cid) {
        await prisma.affiliateMember.upsert({
          where: { affiliateId_cid: { affiliateId, cid } },
          update: { active: true },
          create: { affiliateId, cid }
        });
        if (!aff.hasMembers) {
          await prisma.affiliate.update({ where: { id: affiliateId }, data: { hasMembers: true } });
          await loadAffiliateOwners();
        }
      }
    }
  } else {
    await prisma.userAdditionalRole.deleteMany({ where: { cid, role } });
    if (role === 'WF_TEAM') teamMemberCids.delete(cid);
    if (role === 'WF_AFFILIATE') affiliateCids.delete(cid);
    if (role === 'WF_ATC') wfAtcCids.delete(cid);

    // Untagging WF Affiliate also drops their memberships — the Discord
    // roster is built from AffiliateMember rows, so leaving them behind would
    // keep granting server roles to someone whose portal role was revoked.
    if (role === 'WF_AFFILIATE') {
      await prisma.affiliateMember.deleteMany({ where: { cid } }).catch(() => null);
    }
  }
  res.json({ ok: true });
});

/* ===== ADMIN PERMISSION TOGGLE ===== */
app.post('/admin/api/admin-permissions/toggle', requireAdmin, async (req, res) => {
  const callerCid = Number(req.session?.user?.data?.cid);
  // Only super admins can manage admin permissions
  if (!isSuperAdmin(callerCid)) return res.status(403).json({ error: 'Only the super admin can manage admin permissions' });

  const cid = Number(req.body?.cid);
  const page = String(req.body?.page || '');
  const enabled = !!req.body?.enabled;

  if (!cid) return res.status(400).json({ error: 'CID required' });
  if (!ADMIN_PAGE_KEYS.includes(page)) return res.status(400).json({ error: 'Invalid page key' });
  // Cannot modify super admin permissions
  if (isSuperAdmin(cid)) return res.status(403).json({ error: 'Cannot modify super admin permissions' });

  if (enabled) {
    await prisma.adminPermission.upsert({
      where: { cid_page: { cid, page } },
      update: {},
      create: { cid, page }
    });
    if (!adminPermissions.has(cid)) adminPermissions.set(cid, new Set());
    adminPermissions.get(cid).add(page);
  } else {
    await prisma.adminPermission.deleteMany({ where: { cid, page } });
    const perms = adminPermissions.get(cid);
    if (perms) { perms.delete(page); if (!perms.size) adminPermissions.delete(cid); }
  }
  res.json({ ok: true });
});

app.post('/admin/api/admin-permissions/toggle-all', requireAdmin, async (req, res) => {
  const callerCid = Number(req.session?.user?.data?.cid);
  if (!isSuperAdmin(callerCid)) return res.status(403).json({ error: 'Only the super admin can manage admin permissions' });

  const cid = Number(req.body?.cid);
  const enabled = !!req.body?.enabled;

  if (!cid) return res.status(400).json({ error: 'CID required' });
  if (isSuperAdmin(cid)) return res.status(403).json({ error: 'Cannot modify super admin permissions' });

  if (enabled) {
    // Grant all pages
    for (const page of ADMIN_PAGE_KEYS) {
      await prisma.adminPermission.upsert({
        where: { cid_page: { cid, page } },
        update: {},
        create: { cid, page }
      });
    }
    adminPermissions.set(cid, new Set(ADMIN_PAGE_KEYS));
  } else {
    // Revoke all pages
    await prisma.adminPermission.deleteMany({ where: { cid } });
    adminPermissions.delete(cid);
  }
  res.json({ ok: true });
});

