// ── VATCAN push hooks ────────────────────────────────────────────────────
// Each call queues a debounced push to VATCAN for the given WF sector.
// A flurry of book/cancel within ~750ms coalesces into one push, so a
// "bulk cancel" or rapid re-booking only generates one network call.
//
// We also track which sectors changed since their last successful push so
// the periodic safety sweep below can re-push if a one-off network blip
// dropped the update silently.
const vatcanDirtyWfs = new Set();

function vatcanResolveEventIdForWf(wfNum) {
  return (async () => {
    const wf = String(wfNum).toUpperCase();
    const row = await prisma.wfScheduleRow.findFirst({
      where: { eventId: activeEventId || undefined, number: wf },
      select: { vatcanEventId: true }
    }).catch(() => null);
    return row?.vatcanEventId || null;
  })();
}

// Slot keys look like "FROM-TO|DATE|DEPTIME". Walk adminSheetCache to find
// the WF number for one. Returns null if no matching schedule row.
function wfNumberForSlotKey(slotKey) {
  if (!slotKey || typeof slotKey !== 'string') return null;
  const parts = slotKey.split('|');
  if (parts.length < 3) return null;
  const fromTo = parts[0].split('-');
  if (fromTo.length !== 2) return null;
  const [from, to] = fromTo;
  const date = parts[1], depTime = parts[2];
  const sched = (adminSheetCache || []).find(r =>
    r?.from === from && r?.to === to && r?.date_utc === date && r?.dep_time_utc === depTime
  );
  return sched?.number || null;
}

// Convenience: queue a VATCAN push given any slotKey (looks up the WF).
function vatcanPushForSlotKey(slotKey) {
  if (!vatcanIsEnabled()) return;
  const wf = wfNumberForSlotKey(slotKey);
  if (wf) vatcanPushForWf(wf);
}

function vatcanPushForWf(wf) {
  if (!vatcanIsEnabled()) return;
  vatcanDirtyWfs.add(String(wf).toUpperCase());
  vatcanQueueSectorPush({
    wf: String(wf).toUpperCase(),
    getEventId: () => vatcanResolveEventIdForWf(wf),
    getBookings: () => {
      const out = buildSlotsForWf(wf);
      return out ? out.bookings : [];
    },
    onLog: (lvl, msg) => (lvl === 'error' ? console.error : console.log)(msg)
  });
  // Mark clean after a successful push (the lib stamps LAST_RESULT.ok).
  setTimeout(() => {
    const r = vatcanGetLastResult(String(wf).toUpperCase());
    if (r?.ok) vatcanDirtyWfs.delete(String(wf).toUpperCase());
  }, 2000);
}

// Startup reconcile — pushes are only queued by booking mutations, and the
// dirty set lives in memory, so anything that changed while the server was
// down (a deploy, a direct DB edit) never reaches VATCAN. Re-push every
// flow-restricted sector once per boot so VATCAN always matches the DB.
function vatcanReconcileOnStartup() {
  if (!vatcanIsEnabled()) return;
  const wfs = (adminSheetCache || [])
    .filter(r => r?.number && r.from && r.to)
    .filter(r => (sharedFlowTypes[`${r.from}-${r.to}`] || 'NONE') !== 'NONE')
    .map(r => r.number);
  if (!wfs.length) return;
  console.log(`[VATCAN] Startup reconcile: re-pushing ${wfs.length} flow-restricted sector(s)`);
  // Stagger so a heavily-restricted route doesn't burst the API in one tick.
  wfs.forEach((wf, i) => setTimeout(() => vatcanPushForWf(wf), i * 400));
}

// Periodic safety sweep — re-push any sector whose last push wasn't a clean
// OK in the last 5 min. Catches rare cases where the debounced push lost
// to a crash, timeout, or transient VATCAN 5xx.
if (vatcanIsEnabled()) {
  setInterval(() => {
    if (!vatcanDirtyWfs.size) return;
    for (const wf of [...vatcanDirtyWfs]) {
      const r = vatcanGetLastResult(wf);
      const fresh = r?.ok && (Date.now() - r.at) < 5 * 60 * 1000;
      if (fresh) { vatcanDirtyWfs.delete(wf); continue; }
      vatcanPushForWf(wf);
    }
  }, 60 * 1000);
}

app.post('/api/tobt/cancel', requireLogin, async (req, res) => {
  try {
    const { slotKey } = req.body;
    if (!slotKey) {
      return res.status(400).json({ error: 'Missing slotKey' });
    }

    const cid = Number(req.session.user.data.cid);
    const bookingKey = `${cid}:${slotKey}`;

    const booking = tobtBookingsByKey[bookingKey];
    if (!booking) {
      return res.status(404).json({
        error: 'Booking not found or already cancelled.'
      });
    }

    // 🔥 Delete from DB (MODEL 2: cid + slotKey)
    await prisma.tobtBooking.deleteMany({
      where: {
        cid,
        slotKey
      }
    });

    // 🔥 Delete from memory
    deleteBookingByBookingKey(bookingKey);

    if (tobtBookingsByCid[cid]) {
      tobtBookingsByCid[cid].delete(bookingKey);
      if (tobtBookingsByCid[cid].size === 0) {
        delete tobtBookingsByCid[cid];
      }
    }

    // 🔔 Notify clients
    emitToIcao(booking.from, 'departures:update');
    emitToIcao(
      booking.from,
      'unassignedTobtUpdate',
      buildUnassignedTobtsForICAO(booking.from)
    );

    vatcanPushForSlotKey(slotKey);
    return res.json({ success: true });

  } catch (err) {
    console.error('[TOBT] Cancel failed:', err);
    return res.status(500).json({ error: 'Failed to cancel booking' });
  }
});

app.post('/api/tobt/team-cancel', requireLogin, requireTeamMember, async (req, res) => {
  try {
    const { slotKey, bookingCid } = req.body;
    if (!slotKey || !bookingCid) {
      return res.status(400).json({ error: 'Missing slotKey or bookingCid' });
    }

    const targetCid = Number(bookingCid);
    const bookingKey = `${targetCid}:${slotKey}`;
    const booking = tobtBookingsByKey[bookingKey];
    if (!booking) {
      return res.status(404).json({ error: 'Booking not found or already cancelled.' });
    }

    // Verify the booking's callsign belongs to the requesting user's team
    const myCid = Number(req.session.user.data.cid);
    const myTeamRow = await prisma.userAdditionalRole.findUnique({
      where: { cid_role: { cid: myCid, role: 'WF_TEAM' } }
    }).catch(() => null);
    if (!myTeamRow?.teamName) {
      return res.status(403).json({ error: 'You are not assigned to a team.' });
    }
    const myTeamCallsigns = new Set();
    const teamRows = await prisma.officialTeam.findMany({
      where: { participatingWf26: true },
      select: { teamName: true, callsign: true }
    });
    teamRows.forEach(t => {
      if (String(t.teamName || '').trim().toUpperCase() === myTeamRow.teamName)
        myTeamCallsigns.add(String(t.callsign).toUpperCase());
    });

    if (!myTeamCallsigns.has(String(booking.callsign).toUpperCase())) {
      return res.status(403).json({ error: 'This booking does not belong to your team.' });
    }

    // Delete from DB
    await prisma.tobtBooking.deleteMany({ where: { cid: targetCid, slotKey } });

    // Delete from memory
    deleteBookingByBookingKey(bookingKey);

    if (tobtBookingsByCid[targetCid]) {
      tobtBookingsByCid[targetCid].delete(bookingKey);
      if (tobtBookingsByCid[targetCid].size === 0) {
        delete tobtBookingsByCid[targetCid];
      }
    }

    // Notify clients
    emitToIcao(booking.from, 'departures:update');
    emitToIcao(booking.from, 'unassignedTobtUpdate', buildUnassignedTobtsForICAO(booking.from));

    vatcanPushForSlotKey(slotKey);
    return res.json({ success: true });
  } catch (err) {
    console.error('[TOBT] Team cancel failed:', err);
    return res.status(500).json({ error: 'Failed to cancel booking' });
  }
});


