app.post('/api/tobt/book', requireLogin, async (req, res) => {
  try {
    // 1️⃣ Validate input
    const { slotKey, callsign: enteredCid, manual, teamBooking, teamCallsign } = req.body;
    if (!slotKey || !enteredCid) {
      return res.status(400).json({ error: 'Missing parameters' });
    }

    // 2️⃣ Extract user basics
    const userData = req.session.user.data;
    const cid = Number(userData.cid);

    // Team booking: a WF_TEAM member booking against their team owner's CID.
    // Validate the viewer is a team member whose linked team's mainCid matches
    // the entered CID (prevents users claiming to book for a team they don't
    // belong to).
    if (teamBooking) {
      if (!isTeamMember(cid)) {
        return res.status(403).json({ error: 'Not a team member.' });
      }
      const wfTeamRow = await prisma.userAdditionalRole.findUnique({
        where: { cid_role: { cid, role: 'WF_TEAM' } }
      });
      if (!wfTeamRow?.teamName) {
        return res.status(403).json({ error: 'Your team is not linked.' });
      }
      const allTeams = await prisma.officialTeam.findMany({
        select: { teamName: true, mainCid: true, participatingWf26: true }
      });
      const match = allTeams.find(t =>
        String(t.teamName || '').trim().toUpperCase() === wfTeamRow.teamName &&
        t.participatingWf26 &&
        Number(t.mainCid) === Number(enteredCid)
      );
      if (!match) {
        return res.status(403).json({ error: 'Team owner CID mismatch or team not participating.' });
      }
    } else if (!manual && String(enteredCid).trim() !== String(cid)) {
      return res.status(403).json({ error: 'CID does not match your logged-in account.' });
    }

    // 3️⃣ Parse slotKey: FROM-TO|Date|DepTime|TOBT
    // 3️⃣ Parse slotKey
// 3️⃣ Parse slotKey
const parts = slotKey.split('|');

let from, to, dateUtc, depTimeUtc, tobtTimeUtc;

// BOOKING-ONLY
if (parts.length === 3) {
  const [sectorPart, dateUtcRaw, depTimeUtcRaw] = parts;
  [from, to] = sectorPart.split('-');
  dateUtc = dateUtcRaw;
  depTimeUtc = depTimeUtcRaw;
  tobtTimeUtc = null;

// NORMAL SLOT
} else if (parts.length === 4) {
  const [sectorPart, dateUtcRaw, depTimeUtcRaw, tobtRaw] = parts;
  [from, to] = sectorPart.split('-');
  dateUtc = dateUtcRaw;
  depTimeUtc = depTimeUtcRaw;
  tobtTimeUtc = tobtRaw;

} else {
  return res.status(400).json({ error: 'Invalid slot key format' });
}

if (!from || !to) {
  return res.status(400).json({ error: 'Invalid sector format' });
}

const fromIcao = from.toUpperCase();

// ✅ MISSING LINE (THIS FIXES EVERYTHING)
const isBookingOnly = tobtTimeUtc === null;

// 4️⃣ Decide assignment mode
// Booking-only is ALWAYS a pilot booking
const wantsManual = !isBookingOnly && manual === true;



    // Permission to do a manual assignment
    const canManualAssign = wantsManual && canEditIcao(userData, fromIcao);

    // Pilot booking must have a CID
    if (!canManualAssign && !cid) {
      return res.status(400).json({ error: 'Invalid pilot booking' });
    }

    // 5️⃣ Prevent double booking (TOBT slots only — booking-only allows multiple users)
    if (!isBookingOnly && isSlotTaken(slotKey)) {
      return res.status(409).json({ error: 'Slot already booked' });
    }

    // 6️⃣ Determine target CID — the team owner for team bookings, the pilot's
    // CID for a manual ATC assignment, otherwise the logged-in user.
    const targetCid = (manual || teamBooking) ? Number(enteredCid) : cid;

    // 8️⃣ Prevent duplicate sector + callsign
    const sectorKey = parts.slice(0, 3).join('|');

    // block duplicates per-user per-sector (MODEL 2)
for (const existing of Object.values(tobtBookingsByKey)) {
  if (existing.cid !== targetCid) continue;

  const existingSectorKey = `${existing.from}-${existing.to}|${existing.dateUtc}|${existing.depTimeUtc}`;
  if (existingSectorKey === sectorKey) {
    return res.status(409).json({
      error: 'This pilot already has a booking for this sector.'
    });
  }
}


    // 9️⃣ Persist to DB — always store the target pilot's CID
    const storedCid = targetCid;

    // For team bookings, store the team's callsign so it appears
    // on the Our Bookings page (which filters by team callsigns).
    let normalizedCallsign = String(targetCid);
    if (teamBooking) {
      const bookerTeamRow = await prisma.userAdditionalRole.findUnique({
        where: { cid_role: { cid, role: 'WF_TEAM' } }
      }).catch(() => null);
      if (bookerTeamRow?.teamName) {
        const allTeamCs = await prisma.officialTeam.findMany({
          where: { participatingWf26: true },
          select: { teamName: true, callsign: true }
        }).catch(() => []);
        const myTeamCs = allTeamCs
          .filter(t => String(t.teamName || '').trim().toUpperCase() === bookerTeamRow.teamName)
          .map(t => String(t.callsign || '').toUpperCase());
        // Use client-provided callsign if valid, otherwise fall back to first
        if (teamCallsign && myTeamCs.includes(String(teamCallsign).toUpperCase())) {
          normalizedCallsign = String(teamCallsign).toUpperCase();
        } else if (myTeamCs.length > 0) {
          normalizedCallsign = myTeamCs[0];
        }
      }
    }

    await prisma.tobtBooking.create({
      data: {
        slotKey,
        cid: storedCid,
        callsign: normalizedCallsign,
        from: fromIcao,
        to: to.toUpperCase(),
        dateUtc,
        depTimeUtc,
        tobtTimeUtc,
        manual: wantsManual
      }
    });

    // 🔟 Update in-memory cache
    const bookingKey = `${storedCid}:${slotKey}`;
    setBooking({
      bookingKey,
      slotKey,
      cid: storedCid,
      callsign: normalizedCallsign,
      from: fromIcao,
      to: to.toUpperCase(),
      dateUtc,
      depTimeUtc,
      tobtTimeUtc,
      manual: wantsManual
    });

    if (!tobtBookingsByCid[storedCid]) {
      tobtBookingsByCid[storedCid] = new Set();
    }
    tobtBookingsByCid[storedCid].add(bookingKey);


    // 1️⃣2️⃣ Notify clients
    emitToIcao(fromIcao, 'departures:update');
    emitToIcao(fromIcao, 'unassignedTobtUpdate', buildUnassignedTobtsForICAO(fromIcao));

    vatcanPushForSlotKey(slotKey);
    return res.json({ success: true });

  } catch (err) {
    console.error('[TOBT] Booking failed:', err.message || err);
    return res.status(500).json({ error: 'Failed to book TCT slot: ' + (err.message || 'Unknown error') });
  }
});








// Team member: edit another member's per-user perms (same team).
// Requires the viewer to be admin OR have canManageMembers on their WF_TEAM row.
async function requireTeamManager(req, res, next) {
  const cid = Number(req.session?.user?.data?.cid);
  if (!cid) return res.status(403).json({ error: 'Forbidden' });
  if (isAdminUser(cid)) return next();
  const row = await prisma.userAdditionalRole.findUnique({
    where: { cid_role: { cid, role: 'WF_TEAM' } }
  }).catch(() => null);
  // A team's main CID always manages its own members, with or without a
  // WF_TEAM role row of their own.
  if (!row?.canManageMembers) {
    const owned = await prisma.officialTeam.findFirst({
      where: { mainCid: cid }, select: { teamName: true }
    }).catch(() => null);
    if (!owned) return res.status(403).json({ error: 'Not allowed to manage members.' });
    req._viewerTeamName = String(owned.teamName || '').trim().toUpperCase() || null;
    return next();
  }
  req._viewerTeamName = row.teamName || null;
  next();
}

app.post('/api/team/members', requireLogin, requireTeamManager, async (req, res) => {
  const targetCid = Number(req.body?.cid);
  if (!targetCid || !Number.isInteger(targetCid)) return res.status(400).json({ error: 'Invalid CID' });

  const viewerCid = Number(req.session.user.data.cid);
  const viewerTeam = req._viewerTeamName || (await prisma.userAdditionalRole.findUnique({
    where: { cid_role: { cid: viewerCid, role: 'WF_TEAM' } }
  }).catch(() => null))?.teamName || null;
  if (!viewerTeam) return res.status(403).json({ error: 'Your team is not linked.' });

  // Reject if CID is already a WF_TEAM member on some team
  const existing = await prisma.userAdditionalRole.findUnique({
    where: { cid_role: { cid: targetCid, role: 'WF_TEAM' } }
  });
  if (existing) {
    if (existing.teamName === viewerTeam) return res.status(409).json({ error: 'Already a member of this team.' });
    return res.status(409).json({ error: 'CID is already assigned to another team.' });
  }

  const data = {
    cid: targetCid,
    role: 'WF_TEAM',
    teamName: viewerTeam,
    // New members start with view-only access — the team grants booking edit
    // and member management explicitly on the Manage Members page.
    canEditBookings: req.body?.canEditBookings === true,
    canManageMembers: !!req.body?.canManageMembers,
    participating: req.body?.participating !== false
  };
  await prisma.userAdditionalRole.create({ data });
  teamMemberCids.add(targetCid);
  if (data.canManageMembers) teamManagerCids.add(targetCid);
  return res.json({ success: true });
});

app.post('/api/team/members/:cid/perms', requireLogin, requireTeamManager, async (req, res) => {
  const targetCid = Number(req.params.cid);
  if (!targetCid) return res.status(400).json({ error: 'Invalid CID' });
  const viewerTeam = req._viewerTeamName || (await prisma.userAdditionalRole.findUnique({
    where: { cid_role: { cid: Number(req.session.user.data.cid), role: 'WF_TEAM' } }
  }).catch(() => null))?.teamName || null;

  const target = await prisma.userAdditionalRole.findUnique({
    where: { cid_role: { cid: targetCid, role: 'WF_TEAM' } }
  });
  if (!target) return res.status(404).json({ error: 'Not a team member.' });
  if (viewerTeam && target.teamName !== viewerTeam) {
    return res.status(403).json({ error: 'Member is not in your team.' });
  }

  // Account holders are managed via the admin's Official Teams page, not here.
  const ownerRow = await prisma.officialTeam.findFirst({
    where: { teamName: { equals: target.teamName || '' }, mainCid: targetCid }
  });
  if (ownerRow) {
    return res.status(403).json({ error: 'Managed by Admins.' });
  }

  const data = {};
  if (typeof req.body?.canEditBookings === 'boolean') data.canEditBookings = req.body.canEditBookings;
  if (typeof req.body?.canManageMembers === 'boolean') data.canManageMembers = req.body.canManageMembers;
  if (typeof req.body?.participating === 'boolean') data.participating = req.body.participating;
  if (!Object.keys(data).length) return res.status(400).json({ error: 'No fields to update' });

  await prisma.userAdditionalRole.update({ where: { id: target.id }, data });

  // Keep the in-memory manager cache in step — the sidebar's Manage Members
  // link and the page gate read teamManagerCids, which was otherwise only
  // rebuilt at boot (a fresh grant stayed invisible until a redeploy).
  if (data.canManageMembers === true) {
    teamManagerCids.add(targetCid);
  } else if (data.canManageMembers === false && !teamOwnerCids.has(targetCid)) {
    teamManagerCids.delete(targetCid);
  }
  return res.json({ success: true });
});

app.delete('/api/team/members/:cid', requireLogin, requireTeamManager, async (req, res) => {
  const targetCid = Number(req.params.cid);
  if (!targetCid) return res.status(400).json({ error: 'Invalid CID' });
  const viewerCid = Number(req.session.user.data.cid);
  if (targetCid === viewerCid) return res.status(400).json({ error: 'Cannot remove yourself.' });
  const viewerTeam = req._viewerTeamName || (await prisma.userAdditionalRole.findUnique({
    where: { cid_role: { cid: viewerCid, role: 'WF_TEAM' } }
  }).catch(() => null))?.teamName || null;

  const target = await prisma.userAdditionalRole.findUnique({
    where: { cid_role: { cid: targetCid, role: 'WF_TEAM' } }
  });
  if (!target) return res.status(404).json({ error: 'Not a team member.' });
  if (viewerTeam && target.teamName !== viewerTeam) {
    return res.status(403).json({ error: 'Member is not in your team.' });
  }

  // Account holders can't be removed here; use Official Teams admin.
  const ownerRow = await prisma.officialTeam.findFirst({
    where: { teamName: { equals: target.teamName || '' }, mainCid: targetCid }
  });
  if (ownerRow) {
    return res.status(403).json({ error: 'Managed by Admins.' });
  }

  await prisma.userAdditionalRole.delete({ where: { id: target.id } });
  teamMemberCids.delete(targetCid);
  if (!teamOwnerCids.has(targetCid)) teamManagerCids.delete(targetCid);
  return res.json({ success: true });
});

// Team member: update the CID + callsign on a booking owned by their team.
// Authorization: viewer must be a WF_TEAM member, and the booking's current
// callsign must match one of the team's OfficialTeam callsigns (case-insensitive).
app.post('/api/team/bookings/update', requireLogin, requireTeamMember, async (req, res) => {
  try {
    const sessionCid = Number(req.session.user.data.cid);
    const { slotKey, cid: newCidRaw, callsign: newCallsignRaw, bookingCid: bookingCidRaw } = req.body || {};
    if (!slotKey) return res.status(400).json({ error: 'Missing slotKey' });
    const origBookingCid = bookingCidRaw != null ? Number(bookingCidRaw) : null;
    const newCid = Number(newCidRaw);
    const newCallsign = String(newCallsignRaw || '').trim().toUpperCase();
    if (!newCid || !Number.isInteger(newCid)) return res.status(400).json({ error: 'Invalid CID' });
    if (!/^[A-Z0-9]{2,10}$/.test(newCallsign)) return res.status(400).json({ error: 'Invalid callsign' });

    // Resolve the viewer's team + allowed callsigns + allowed assignee CIDs
    const wfTeamRow = await prisma.userAdditionalRole.findUnique({
      where: { cid_role: { cid: sessionCid, role: 'WF_TEAM' } }
    });
    if (!wfTeamRow?.teamName) return res.status(403).json({ error: 'Your team is not linked.' });
    if (wfTeamRow.canEditBookings === false) return res.status(403).json({ error: 'You do not have permission to edit bookings.' });
    const [teamRows, teamMemberRoles] = await Promise.all([
      prisma.officialTeam.findMany({
        where: { participatingWf26: true },
        select: { teamName: true, callsign: true, mainCid: true }
      }),
      prisma.userAdditionalRole.findMany({
        where: { role: 'WF_TEAM' },
        select: { cid: true, teamName: true }
      })
    ]);
    const myTeam = teamRows.filter(t => String(t.teamName || '').trim().toUpperCase() === wfTeamRow.teamName);
    const teamCallsignSet = new Set(myTeam.map(t => String(t.callsign).toUpperCase()));
    if (!teamCallsignSet.size) return res.status(403).json({ error: 'Team has no participating callsigns.' });
    const allowedAssignees = new Set();
    myTeam.forEach(t => { if (t.mainCid) allowedAssignees.add(Number(t.mainCid)); });
    teamMemberRoles.forEach(r => {
      if (String(r.teamName || '').trim().toUpperCase() === wfTeamRow.teamName && r.cid) {
        allowedAssignees.add(Number(r.cid));
      }
    });
    if (!allowedAssignees.has(newCid)) {
      return res.status(403).json({ error: 'Pilot is not a member of your team.' });
    }

    // Find the booking for this slotKey owned by a team callsign. We can't
    // use bare `findFirst({slotKey})` because BOOKING_ONLY sectors have many
    // bookings sharing one slotKey — that would non-deterministically pick
    // some other pilot's row and bail out with a false "Not your team's
    // booking" error.
    //
    // Prefer the client-supplied origBookingCid (deterministic — picks the
    // exact row the user clicked Edit on). Fall back to "any team-owned
    // booking on this slot" for backward compat.
    const dbBooking = origBookingCid != null
      ? await prisma.tobtBooking.findFirst({
          where: { slotKey, cid: origBookingCid, callsign: { in: [...teamCallsignSet] } }
        })
      : await prisma.tobtBooking.findFirst({
          where: { slotKey, callsign: { in: [...teamCallsignSet] } }
        });
    if (!dbBooking) return res.status(404).json({ error: "Booking not found for your team on this slot" });

    const oldCid = Number(dbBooking.cid);

    // Update DB by id so we can cleanly change cid without unique clashes
    await prisma.tobtBooking.update({
      where: { id: dbBooking.id },
      data: { cid: newCid, callsign: newCallsign }
    });

    // Update in-memory caches
    const oldBookingKey = `${oldCid}:${slotKey}`;
    const newBookingKey = `${newCid}:${slotKey}`;
    const existing = tobtBookingsByKey[oldBookingKey] || getAnyBookingForSlot(slotKey);
    const updated = {
      ...(existing || {}),
      slotKey,
      cid: newCid,
      callsign: newCallsign,
      from: dbBooking.from,
      to: dbBooking.to,
      dateUtc: dbBooking.dateUtc,
      depTimeUtc: dbBooking.depTimeUtc,
      tobtTimeUtc: dbBooking.tobtTimeUtc
    };
    if (oldCid !== newCid) {
      deleteBookingByBookingKey(oldBookingKey);
      if (tobtBookingsByCid[oldCid]) tobtBookingsByCid[oldCid].delete(oldBookingKey);
    }
    setBooking(updated);
    if (!tobtBookingsByCid[newCid]) tobtBookingsByCid[newCid] = new Set();
    tobtBookingsByCid[newCid].add(newBookingKey);

    vatcanPushForSlotKey(slotKey);
    return res.json({ success: true });
  } catch (err) {
    console.error('[TEAM] Update booking failed:', err);
    return res.status(500).json({ error: 'Failed to update booking' });
  }
});

app.post('/api/tobt/update-callsign', requireLogin, async (req, res) => {
  try {
    const { slotKey, callsign } = req.body;
    if (!slotKey || !callsign) {
      return res.status(400).json({ error: 'Missing parameters' });
    }

    const cid = Number(req.session.user.data.cid);
    const bookingKey = `${cid}:${slotKey}`;

    const booking = tobtBookingsByKey[bookingKey];
    if (!booking) {
      return res.status(403).json({
        error: 'Not your booking'
      });
    }

    const normalizedCallsign = callsign.trim().toUpperCase();

    // Reserved team callsign enforcement
    const teamCheck = await isReservedTeamCallsign(normalizedCallsign, cid);
    if (teamCheck.reserved && !teamCheck.allowed) {
      return res.status(403).json({
        error: `Callsign ${normalizedCallsign} is reserved for an official team.`
      });
    }

    // Update DB (Model 2: cid + slotKey)
    await prisma.tobtBooking.updateMany({
      where: {
        cid,
        slotKey
      },
      data: {
        callsign: normalizedCallsign
      }
    });

    // Update in-memory cache
    booking.callsign = normalizedCallsign;

    return res.json({ success: true });

  } catch (err) {
    console.error('[TOBT] Update callsign failed:', err);
    return res.status(500).json({ error: 'Failed to update callsign' });
  }
});


// 🔒 Reserved Official Team callsign enforcement (UPDATE)



/* ===== AFFILIATE HQ ===== */
// Resolve "the user's primary affiliate":
//   1. Affiliate where user is the main CID (lowest id wins if multiple)
//   2. Otherwise, Affiliate the user belongs to as an AffiliateMember
async function resolveUserAffiliate(cid) {
  let aff = await prisma.affiliate.findFirst({
    where: { cid },
    orderBy: { id: 'asc' }
  });
  if (!aff) {
    const m = await prisma.affiliateMember.findFirst({
      where: { cid },
      orderBy: { id: 'asc' }
    });
    if (m) aff = await prisma.affiliate.findUnique({ where: { id: m.affiliateId } });
  }
  return aff;
}

