// Read-only preview of what a sync would do. The Sync Now button calls this
// first so the admin confirms role REMOVALS before they are applied — the
// hourly cron intentionally has no such gate. Never writes to Discord.
app.get('/admin/api/discord/sync-preview', requireAdmin, async (req, res) => {
  if (!discordConfigured()) return res.status(503).json({ error: 'Discord sync is not configured' });
  try {
    const rosterGroups = await buildDiscordRosterGroups();
    const snap = await getGuildSnapshot();
    if (!snap) return res.status(503).json({ error: 'Could not read the Discord server' });
    const manualCidByDiscordId = await loadDiscordManualLinks();
    const diff = computeRoleDiff({ rosterGroups, members: snap.members, guildRoleNames: snap.roleNames, manualCidByDiscordId });
    const plan = buildApplyPlan(diff);
    // The real sync creates any missing roles itself before applying, so a
    // missing role must not block the preview — report it as "will be
    // created" instead and judge safety as the post-creation run will.
    const safety = isDiffSafeToApply({ ...diff, missingRoles: [] });
    res.json({
      removalsEnabled: removalsEnabled(),
      safe: safety.safe,
      reasons: safety.reasons,
      rolesToCreate: diff.missingRoles,
      totalAdds: plan.totalAdds,
      totalRemovals: plan.totalRemovals,
      removals: plan.ops.filter(o => o.remove.length).map(o => ({ nickname: o.nickname, cid: o.cid, roles: o.remove }))
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Run the role reconcile on demand. Same code path as the hourly cron.
app.post('/admin/api/discord/sync', requireAdmin, async (req, res) => {
  if (!discordConfigured()) return res.status(503).json({ error: 'Discord sync is not configured' });
  try {
    const state = await runDiscordRoleSync({ buildRoster: buildDiscordRosterGroups, loadManualLinks: loadDiscordManualLinks, persistNames: persistDiscordNames, reason: 'manual' });
    if (state.result === 'blocked') return res.status(409).json({ error: 'Blocked: ' + state.message });
    if (state.result === 'error') return res.status(500).json({ error: state.message });
    res.json({ success: true, added: state.added, removed: state.removed, failed: state.failed });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Email a member an invite to the community Discord. Admin-only.
app.post('/admin/api/discord/invite/:cid', requireAdmin, express.json(), async (req, res) => {
  const cid = Number(req.params.cid);
  if (!cid) return res.status(400).json({ error: 'Invalid CID' });

  const inviteUrl = WF_DISCORD_INVITE;
  if (!/^https?:\/\//i.test(inviteUrl)) {
    return res.status(503).json({ error: 'No Discord invite link configured (set DISCORD_INVITE_URL)' });
  }

  try {
    const u = await prisma.user.findUnique({ where: { cid }, select: { name: true, email: true } });
    // The whole point of the button: say plainly when there is nobody to mail.
    if (!u || !u.email) return res.status(404).json({ error: 'No email address on file' });

    const operatorName = String(req.body?.operatorName || '').trim() || 'WorldFlight';
    const isTeam = req.body?.kind !== 'affiliate';

    const transporter = nodemailer.createTransport({
      host: process.env.SMTP_HOST || 'smtp.gmail.com',
      port: Number(process.env.SMTP_PORT) || 587,
      secure: false,
      auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS }
    });
    await transporter.sendMail({
      from: process.env.SMTP_FROM || '"WorldFlight" <noreply@worldflight.center>',
      to: u.email,
      subject: 'WorldFlight — Join our Discord',
      html: buildDiscordInviteEmail({
        memberName: escapeHtml(String(u.name || '').trim().split(/\s+/)[0] || 'there'),
        operatorName: escapeHtml(operatorName),
        isTeam,
        inviteUrl
      })
    });
    console.log(`[DISCORD] Invite emailed to CID ${cid} (${u.email})`);
    res.json({ success: true, email: u.email });
  } catch (e) {
    console.error('[DISCORD] Invite email failed:', e.message);
    res.status(500).json({ error: 'Failed to send: ' + e.message });
  }
});

// Public submission — logged-in users only; CID comes from the session.
// Multipart: text fields + up to 5 setup photos (stored in the DB so they
// survive redeploys on Railway's ephemeral filesystem).
const affApplyUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024, files: 5 }
});
app.post('/api/affiliate-applications', (req, res, next) => {
  affApplyUpload.array('photos', 5)(req, res, (err) => {
    if (err) return res.status(400).json({ error: err.code === 'LIMIT_FILE_SIZE' ? 'Each photo must be under 5 MB' : 'Photo upload failed: ' + err.message });
    next();
  });
}, async (req, res) => {
  const sessUser = req.session?.user?.data;
  const cid = Number(sessUser?.cid);
  if (!cid) return res.status(401).json({ error: 'You must be logged in to apply' });

  const { teamName, callsign, simType, hasMembers, heardAbout, discord, email, website, notes } = req.body || {};
  if (!callsign || !simType) return res.status(400).json({ error: 'Callsign and sim type are required' });
  if (!teamName || !String(teamName).trim()) return res.status(400).json({ error: 'Team name is required' });

  const discordName = String(discord || '').trim();
  const emailAddr = String(email || '').trim();
  if (!discordName) return res.status(400).json({ error: 'Discord username is required' });
  if (!emailAddr) return res.status(400).json({ error: 'Email address is required' });
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailAddr)) return res.status(400).json({ error: 'Enter a valid email address' });

  const photos = (req.files || []).filter(f => /^image\//.test(f.mimetype));
  if ((req.files || []).length > photos.length) {
    return res.status(400).json({ error: 'Only image files can be attached' });
  }

  try {
    const [pending, existingAff] = await Promise.all([
      prisma.affiliateApplication.findFirst({ where: { cid, status: 'pending' } }),
      prisma.affiliate.findFirst({ where: { cid } })
    ]);
    if (pending) return res.status(400).json({ error: 'You already have a pending application' });
    if (existingAff) return res.status(400).json({ error: 'This CID is already registered as a WF Affiliate' });

    const created = await prisma.affiliateApplication.create({
      data: {
        teamName: String(teamName).trim().slice(0, 60),
        callsign: String(callsign).trim().toUpperCase().slice(0, 10),
        simType: String(simType).trim().toUpperCase().slice(0, 30),
        cid,
        hasMembers: String(hasMembers) === 'true',
        heardAbout: heardAbout ? String(heardAbout).trim().slice(0, 60) : null,
        discord: discordName.slice(0, 60),
        email: emailAddr.slice(0, 120),
        // Force an http(s) scheme so the admin-side link can never be javascript: etc.
        website: website && String(website).trim()
          ? (/^https?:\/\//i.test(String(website).trim()) ? String(website).trim() : 'https://' + String(website).trim()).slice(0, 200)
          : null,
        notes: notes ? String(notes).trim().slice(0, 1000) : null,
        source: 'public'
      }
    });

    for (const f of photos) {
      await prisma.affiliateApplicationPhoto.create({
        data: {
          applicationId: created.id,
          filename: String(f.originalname || 'photo').slice(0, 120),
          mime: f.mimetype,
          data: f.buffer
        }
      });
    }

    console.log(`[AFF-APP] New public application #${created.id} from CID ${cid} (${created.callsign}, ${photos.length} photos)`);

    // Confirmation email. Never fail the application over a mail problem —
    // the row is already saved and the admin queue is the source of truth.
    try {
      const transporter = nodemailer.createTransport({
        host: process.env.SMTP_HOST || 'smtp.gmail.com',
        port: Number(process.env.SMTP_PORT) || 587,
        secure: false,
        auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS }
      });
      await transporter.sendMail({
        from: process.env.SMTP_FROM || '"WorldFlight" <noreply@worldflight.center>',
        to: emailAddr,
        subject: 'WorldFlight — Affiliate Application Received',
        html: buildAffiliateApplicationEmail({
          applicantName: escapeHtml(String(sessUser?.personal?.name_first || '').trim() || 'there'),
          teamName: escapeHtml(created.teamName || created.callsign),
          callsign: escapeHtml(created.callsign),
          simType: escapeHtml(created.simType),
          cid,
          discordInvite: WF_DISCORD_INVITE
        })
      });
      console.log(`[AFF-APP] Confirmation email sent for #${created.id}`);
    } catch (emailErr) {
      console.error('[AFF-APP] Confirmation email failed:', emailErr.message);
    }

    res.json({ success: true, id: created.id });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

