app.post('/admin/api/affiliate-applications/:id/approve', requireAdmin, async (req, res) => {
  const id = Number(req.params.id);
  const adminCid = Number(req.session?.user?.data?.cid) || null;
  const maskName = !!(req.body?.maskName);
  try {
    const appRow = await prisma.affiliateApplication.findUnique({ where: { id } });
    if (!appRow) return res.status(404).json({ error: 'Application not found' });
    if (appRow.status !== 'pending') return res.status(400).json({ error: 'Application already ' + appRow.status });

    const created = await prisma.affiliate.create({
      data: {
        name: appRow.teamName || null,
        callsign: appRow.callsign,
        simType: appRow.simType,
        cid: appRow.cid,
        maskName,
        // Public applicants don't pick a year — active since the year we approve
        sinceYear: appRow.sinceYear || new Date().getUTCFullYear(),
        hasMembers: appRow.hasMembers,
        // The application's free-text notes seed the public bio, so they get
        // the same 360-char cap; the full notes stay on the application row.
        description: cleanBio(appRow.notes),
        website: appRow.website || null,
        // Without this the row defaults to 0 and jumps to the front of every
        // ordered list — approved affiliates belong at the end.
        sortOrder: await resolveSortOrder(null, prisma.affiliate),
        participatingWf26: true
      }
    });

    // First application photo becomes the affiliate's public profile photo
    const firstPhoto = await prisma.affiliateApplicationPhoto.findFirst({
      where: { applicationId: id },
      orderBy: { id: 'asc' }
    }).catch(() => null);
    if (firstPhoto) {
      await prisma.profilePhoto.upsert({
        where: { entityType_entityId: { entityType: 'affiliate', entityId: created.id } },
        update: { mime: firstPhoto.mime, data: firstPhoto.data, updatedAt: new Date() },
        create: { entityType: 'affiliate', entityId: created.id, mime: firstPhoto.mime, data: firstPhoto.data }
      }).catch(() => {});
    }

    if (!isAdminUser(appRow.cid)) {
      await prisma.userAdditionalRole.upsert({
        where: { cid_role: { cid: appRow.cid, role: 'WF_AFFILIATE' } },
        update: {},
        create: { cid: appRow.cid, role: 'WF_AFFILIATE' }
      });
      affiliateCids.add(appRow.cid);
    }
    await loadAffiliateOwners();
    await loadAffiliates();

    await prisma.affiliateApplication.update({
      where: { id },
      data: { status: 'approved', decidedBy: adminCid, decidedAt: new Date(), affiliateId: created.id }
    });

    autoAssignTeamThenAffiliate({ reason: `affiliate application ${id} approved` }).catch(() => {});
    console.log(`[AFF-APP] Application #${id} (${appRow.callsign}) approved by ${adminCid} — affiliate ${created.id} created`);

    await sendAffiliateDecisionEmail(appRow, 'approved', {
      html: buildAffiliateApprovedEmail({
        applicantName: await applicantFirstName(appRow.cid),
        callsign: escapeHtml(appRow.callsign),
        hasMembers: !!appRow.hasMembers,
        hasProfilePhoto: !!firstPhoto
      }),
      subject: 'WorldFlight — Affiliate Application Approved'
    });

    res.json({ success: true, affiliateId: created.id });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/admin/api/affiliate-applications/:id/decline', requireAdmin, async (req, res) => {
  const id = Number(req.params.id);
  const adminCid = Number(req.session?.user?.data?.cid) || null;
  // The reason is written by the admin in the decline modal and goes out in
  // the rejection email, so it isn't optional.
  const reason = String(req.body?.reason || '').trim();
  if (!reason) return res.status(400).json({ error: 'A reason is required — it is sent to the applicant' });
  try {
    const appRow = await prisma.affiliateApplication.findUnique({ where: { id } });
    if (!appRow) return res.status(404).json({ error: 'Application not found' });
    if (appRow.status !== 'pending') return res.status(400).json({ error: 'Application already ' + appRow.status });
    await prisma.affiliateApplication.update({
      where: { id },
      data: {
        status: 'declined',
        decidedBy: adminCid,
        decidedAt: new Date(),
        declineReason: reason.slice(0, 1000)
      }
    });
    console.log(`[AFF-APP] Application #${id} (${appRow.callsign}) declined by ${adminCid}`);

    await sendAffiliateDecisionEmail(appRow, 'declined', {
      html: buildAffiliateDeclinedEmail({
        applicantName: await applicantFirstName(appRow.cid),
        callsign: escapeHtml(appRow.callsign),
        reason: escapeHtml(reason.slice(0, 1000))
      }),
      subject: 'WorldFlight — Affiliate Application Update'
    });

    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

