// Delete Affiliate
app.delete('/api/admin/affiliates/:id', requireAdmin, async (req, res) => {
  const id = Number(req.params.id);
  if (!id) return res.status(400).json({ error: 'Invalid id' });

  const existing = await prisma.affiliate.findUnique({ where: { id }, select: { cid: true, callsign: true } }).catch(() => null);
  const memberRows = await prisma.affiliateMember.findMany({ where: { affiliateId: id }, select: { cid: true } }).catch(() => []);

  // Release any slots this affiliate holds before the row goes. Otherwise the
  // booking lingers under a callsign that no longer exists: the slot stays out
  // of the pool, the pilot still appears in the VATCAN list, and the sector
  // reads as fuller than it is. Mirrors the affiliate-side fleet delete.
  const deletedCs = String(existing?.callsign || '').toUpperCase();
  let released = 0;
  if (deletedCs) {
    const bookings = await prisma.tobtBooking.findMany({ where: { callsign: deletedCs } }).catch(() => []);
    for (const bk of bookings) {
      await prisma.tobtBooking.delete({ where: { id: bk.id } }).catch(() => null);
      const bookingKey = `${Number(bk.cid)}:${bk.slotKey}`;
      deleteBookingByBookingKey(bookingKey);
      if (tobtBookingsByCid[Number(bk.cid)]) tobtBookingsByCid[Number(bk.cid)].delete(bookingKey);
      try { io.emit('bookingCancelled', { slotKey: bk.slotKey }); } catch {}
      vatcanPushForSlotKey(bk.slotKey);
      released++;
    }
  }

  await prisma.affiliateSectorClaim.deleteMany({ where: { affiliateId: id } }).catch(() => null);
  await prisma.affiliateMember.deleteMany({ where: { affiliateId: id } }).catch(() => null);
  await prisma.affiliate.delete({ where: { id } }).catch(() => null);
  await loadAffiliateOwners();
  if (released) console.log(`[AFFILIATE] Deleted ${deletedCs} — released ${released} booking(s)`);

  // Drop WF_AFFILIATE from anyone this delete orphaned (main + members)
  if (existing) await revokeAffiliateRoleIfOrphaned(existing.cid);
  for (const m of memberRows) await revokeAffiliateRoleIfOrphaned(m.cid);

  return res.json({ success: true });
});

// Patch Official Team (WF26 toggle or full edit)
app.patch('/api/admin/official-teams/:id', requireAdmin, profilePhotoUpload.single('photo'), async (req, res) => {
  const id = Number(req.params.id);
  if (!id) return res.status(400).json({ error: 'Invalid id' });
  const body = req.body || {};
  const data = {};
  if (body.teamName !== undefined) data.teamName = String(body.teamName).trim();
  if (body.callsign !== undefined) data.callsign = String(body.callsign).trim().toUpperCase();
  if (body.mainCid !== undefined) data.mainCid = Number(body.mainCid);
  if (body.aircraftType !== undefined) data.aircraftType = String(body.aircraftType).trim().toUpperCase();
  if (body.country !== undefined) data.country = String(body.country).trim();
  if (body.sinceYear !== undefined) {
    const yr = body.sinceYear == null || body.sinceYear === '' ? null : Number(body.sinceYear);
    if (yr != null && (!Number.isFinite(yr) || yr < 1990 || yr > 2100)) {
      return res.status(400).json({ error: 'Invalid sinceYear' });
    }
    data.sinceYear = yr;
  }
  if (body.multiSlot !== undefined) data.multiSlot = asBool(body.multiSlot);
  if (body.description !== undefined) data.description = cleanBio(body.description);
  if (body.website !== undefined) data.website = cleanWebsite(body.website);
  if (body.sortOrder !== undefined && String(body.sortOrder).trim() !== '') data.sortOrder = Math.max(0, Number(body.sortOrder) || 0);
  if (body.participatingWf26 !== undefined) data.participatingWf26 = asBool(body.participatingWf26);
  if (!Object.keys(data).length && !req.file) return res.status(400).json({ error: 'No fields to update' });

  const oldRow = data.mainCid ? await prisma.officialTeam.findUnique({ where: { id }, select: { mainCid: true, teamName: true } }).catch(() => null) : null;

  if (Object.keys(data).length) await prisma.officialTeam.update({ where: { id }, data });
  await saveProfilePhoto('team', id, req.file);

  // When mainCid changes via admin, ensure the new CID has a WF_TEAM role row
  // and refresh in-memory sets so the sidebar picks up the change immediately.
  if (data.mainCid && oldRow && data.mainCid !== Number(oldRow.mainCid)) {
    const teamName = data.teamName || String(oldRow.teamName || '').trim();
    await prisma.userAdditionalRole.upsert({
      where: { cid_role: { cid: data.mainCid, role: 'WF_TEAM' } },
      update: { teamName },
      create: { cid: data.mainCid, role: 'WF_TEAM', teamName }
    }).catch(() => {});
    await loadTeamMembers();
    console.log('[TEAM-ADMIN] mainCid changed from ' + oldRow.mainCid + ' to ' + data.mainCid);
  }

  // multiSlot describes the whole team, so keep every aircraft in the fleet in
  // step — otherwise auto-assignment would see a half-flagged fleet.
  if (data.multiSlot !== undefined) {
    const row = await prisma.officialTeam.findUnique({ where: { id }, select: { teamName: true } }).catch(() => null);
    if (row?.teamName) {
      const all = await prisma.officialTeam.findMany({ select: { id: true, teamName: true } });
      const key = String(row.teamName).trim().toUpperCase();
      for (const t of all) {
        if (t.id === id) continue;
        if (String(t.teamName || '').trim().toUpperCase() !== key) continue;
        await prisma.officialTeam.update({ where: { id: t.id }, data: { multiSlot: data.multiSlot } }).catch(() => {});
      }
    }
  }

  autoAssignTeamThenAffiliate({ reason: `team ${id} patched` }).catch(() => {});
  return res.json({ success: true });
});

// Patch Affiliate (WF26 toggle or full edit)
/* Transferring an affiliate's main CID has to carry its existing work across.
   Bookings are keyed by cid, so without this the HQ keeps showing the previous
   holder as the VATSIM account (and VATCAN keeps being pushed their cid) even
   though the affiliate now belongs to someone else. */
async function reassignAffiliateToNewMainCid(affiliateRow, oldCid, newCid) {
  const result = { bookings: 0, claims: 0 };
  if (!affiliateRow) return result;
  oldCid = Number(oldCid);
  newCid = Number(newCid);
  if (!Number.isFinite(oldCid) || !Number.isFinite(newCid) || oldCid === newCid || !oldCid || !newCid) return result;

  const cs = String(affiliateRow.callsign || '').toUpperCase();
  if (cs) {
    const bookings = await prisma.tobtBooking.findMany({ where: { callsign: cs, cid: oldCid } }).catch(() => []);
    for (const bk of bookings) {
      // Update by id so the cid can move without tripping the (cid, slotKey) unique
      const moved = await prisma.tobtBooking.update({ where: { id: bk.id }, data: { cid: newCid } }).catch(() => null);
      if (!moved) continue;

      const oldKey = `${oldCid}:${bk.slotKey}`;
      const newKey = `${newCid}:${bk.slotKey}`;
      const existing = tobtBookingsByKey[oldKey];
      deleteBookingByBookingKey(oldKey);
      if (tobtBookingsByCid[oldCid]) tobtBookingsByCid[oldCid].delete(oldKey);
      setBooking({
        ...(existing || {}),
        slotKey: bk.slotKey,
        cid: newCid,
        callsign: cs,
        from: bk.from,
        to: bk.to,
        dateUtc: bk.dateUtc,
        depTimeUtc: bk.depTimeUtc,
        tobtTimeUtc: bk.tobtTimeUtc
      });
      if (!tobtBookingsByCid[newCid]) tobtBookingsByCid[newCid] = new Set();
      tobtBookingsByCid[newCid].add(newKey);
      vatcanPushForSlotKey(bk.slotKey);
      result.bookings++;
    }
  }

  // Sector claims naming the old main move too. cid 0 is the "not flying"
  // sentinel and never matches a real cid, so it is left alone.
  const claims = await prisma.affiliateSectorClaim.updateMany({
    where: { affiliateId: affiliateRow.id, cid: oldCid },
    data: { cid: newCid }
  }).catch(() => null);
  result.claims = claims?.count || 0;

  if (result.bookings || result.claims) {
    console.log(`[AFFILIATE] ${cs || affiliateRow.id}: main CID ${oldCid} -> ${newCid}, moved ${result.bookings} booking(s) and ${result.claims} claim(s)`);
  }
  return result;
}

app.patch('/api/admin/affiliates/:id', requireAdmin, profilePhotoUpload.single('photo'), async (req, res) => {
  const id = Number(req.params.id);
  if (!id) return res.status(400).json({ error: 'Invalid id' });
  const body = req.body || {};
  const data = {};
  if (body.callsign !== undefined) data.callsign = String(body.callsign).trim().toUpperCase();
  if (body.simType !== undefined) data.simType = String(body.simType).trim();
  if (body.cid !== undefined) data.cid = Number(body.cid);
  if (body.sinceYear !== undefined) {
    const yr = body.sinceYear == null || body.sinceYear === '' ? null : Number(body.sinceYear);
    if (yr != null && (!Number.isFinite(yr) || yr < 1990 || yr > 2100)) {
      return res.status(400).json({ error: 'Invalid sinceYear' });
    }
    data.sinceYear = yr;
  }
  if (body.hasMembers !== undefined) data.hasMembers = asBool(body.hasMembers);
  if (body.multiAircraft !== undefined) data.multiAircraft = asBool(body.multiAircraft);
  if (body.manualCallsigns !== undefined) data.manualCallsigns = asBool(body.manualCallsigns);
  if (body.fleetLimit !== undefined) {
    const fl = body.fleetLimit === '' || body.fleetLimit == null ? null : Number(body.fleetLimit);
    data.fleetLimit = (fl && Number.isFinite(fl) && fl > 0) ? Math.min(fl, 20) : null;
  }
  if (body.name !== undefined) data.name = String(body.name).trim().slice(0, 60) || null;
  if (body.aircraftType !== undefined) data.aircraftType = String(body.aircraftType).trim().toUpperCase().slice(0, 10) || null;
  if (body.description !== undefined) data.description = cleanBio(body.description);
  if (body.website !== undefined) data.website = cleanWebsite(body.website);
  if (body.sortOrder !== undefined && String(body.sortOrder).trim() !== '') data.sortOrder = Math.max(0, Number(body.sortOrder) || 0);
  if (body.participatingWf26 !== undefined) data.participatingWf26 = asBool(body.participatingWf26);
  if (!Object.keys(data).length && !req.file) return res.status(400).json({ error: 'No fields to update' });

  // Remember the previous main CID so a transfer can revoke their role, and
  // move their bookings/claims onto the new holder, below
  const prevRow = data.cid !== undefined
    ? await prisma.affiliate.findUnique({ where: { id }, select: { cid: true, callsign: true } }).catch(() => null)
    : null;

  if (Object.keys(data).length) await prisma.affiliate.update({ where: { id }, data });
  await saveProfilePhoto('affiliate', id, req.file);

  // Carry existing bookings and sector claims over to the new main CID. Uses
  // the post-update callsign so a simultaneous callsign change is respected.
  if (prevRow && data.cid !== undefined && Number(prevRow.cid) !== Number(data.cid)) {
    const current = await prisma.affiliate.findUnique({ where: { id }, select: { id: true, callsign: true } }).catch(() => null);
    await reassignAffiliateToNewMainCid(current, prevRow.cid, data.cid);
  }

  // If the main CID changed, grant WF_AFFILIATE to the new owner so they
  // get the Affiliate HQ sidebar entry. Skip admins (they shouldn't pick up
  // an Affiliate role just from being assigned as Main).
  if (data.cid !== undefined && Number.isFinite(data.cid) && !isAdminUser(data.cid)) {
    await prisma.userAdditionalRole.upsert({
      where: { cid_role: { cid: data.cid, role: 'WF_AFFILIATE' } },
      update: {},
      create: { cid: data.cid, role: 'WF_AFFILIATE' }
    });
    affiliateCids.add(data.cid);
  }
  await loadAffiliateOwners();

  // multiAircraft describes the whole fleet, so keep every affiliate sharing
  // this name in step — otherwise the HQ and public page disagree.
  if (data.multiAircraft !== undefined) {
    const row = await prisma.affiliate.findUnique({ where: { id }, select: { name: true, callsign: true } }).catch(() => null);
    const key = String(row?.name || row?.callsign || '').trim().toUpperCase();
    if (key) {
      const all = await prisma.affiliate.findMany({ select: { id: true, name: true, callsign: true } });
      for (const a of all) {
        if (a.id === id) continue;
        if (String(a.name || a.callsign || '').trim().toUpperCase() !== key) continue;
        await prisma.affiliate.update({ where: { id: a.id }, data: { multiAircraft: data.multiAircraft } }).catch(() => {});
      }
    }
  }

  // Main CID transferred away — revoke the old holder's role if orphaned
  if (prevRow && data.cid !== undefined && Number(prevRow.cid) !== Number(data.cid)) {
    await revokeAffiliateRoleIfOrphaned(prevRow.cid);
  }

  // If they just turned on participation, run auto-assignment (teams first, then affiliates).
  if (data.participatingWf26 === true) {
    autoAssignTeamThenAffiliate({ reason: `affiliate ${id} patched` }).catch(() => {});
  }

  return res.json({ success: true });
});

/* Promote an affiliate to an Official WF Team. A multi-aircraft operator is
   several Affiliate rows sharing a name, so the whole group moves: one
   OfficialTeam row per aircraft, each keeping its callsign, main CID, A/C
   type and profile photo. Sector claims become the team equivalents (cid 0
   sentinel -> opt-out, positive cid -> assignment), members get WF_TEAM roles
   carrying their permissions, then the affiliate side is deleted. Bookings
   are keyed by cid + callsign and both carry over unchanged, so they are not
   touched. Country has no affiliate equivalent and is set to TBD. */
app.post('/api/admin/affiliates/:id/promote', requireAdmin, async (req, res) => {
  const id = Number(req.params.id);
  if (!id) return res.status(400).json({ error: 'Invalid id' });

  try {
    const source = await prisma.affiliate.findUnique({ where: { id } });
    if (!source) return res.status(404).json({ error: 'Affiliate not found' });

    const groupKey = String(source.name || source.callsign || '').trim().toUpperCase();
    const allAffiliates = await prisma.affiliate.findMany({ orderBy: { id: 'asc' } });
    const group = allAffiliates.filter(a => String(a.name || a.callsign || '').trim().toUpperCase() === groupKey);

    const teamName = String(source.name || source.callsign || '').trim().slice(0, 60);
    const existingTeams = await prisma.officialTeam.findMany({ select: { teamName: true } });
    if (existingTeams.some(t => String(t.teamName || '').trim().toUpperCase() === teamName.toUpperCase())) {
      return res.status(409).json({ error: `An Official Team named "${teamName}" already exists` });
    }

    const summary = { teamName, aircraft: 0, membersMoved: 0, membersSkipped: [], optOuts: 0, assignments: 0 };
    const nextSort = await resolveSortOrder(undefined, prisma.officialTeam);

    for (const aff of group) {
      const team = await prisma.officialTeam.create({
        data: {
          teamName,
          callsign: String(aff.callsign || '').trim().toUpperCase(),
          mainCid: Number(aff.cid) || 0,
          aircraftType: String(aff.aircraftType || 'TBD').trim().toUpperCase(),
          country: 'TBD',
          sinceYear: aff.sinceYear,
          multiSlot: !!aff.multiAircraft,
          description: aff.description,
          website: aff.website,
          sortOrder: nextSort,
          participatingWf26: !!aff.participatingWf26
        }
      });
      summary.aircraft++;

      // Profile photo follows its row across
      await prisma.profilePhoto.update({
        where: { entityType_entityId: { entityType: 'affiliate', entityId: aff.id } },
        data: { entityType: 'team', entityId: team.id }
      }).catch(() => null);

      const claims = await prisma.affiliateSectorClaim.findMany({ where: { affiliateId: aff.id } }).catch(() => []);
      for (const c of claims) {
        if (Number(c.cid) === 0) {
          const made = await prisma.teamSectorOptOut.create({
            data: { officialTeamId: team.id, sectorNumber: c.sectorNumber }
          }).catch(() => null);
          if (made) summary.optOuts++;
        } else if (Number(c.cid) > 0) {
          const made = await prisma.teamSectorAssignment.create({
            data: { officialTeamId: team.id, sectorNumber: c.sectorNumber, cid: Number(c.cid) }
          }).catch(() => null);
          if (made) summary.assignments++;
        }
      }
      await prisma.affiliateSectorClaim.deleteMany({ where: { affiliateId: aff.id } }).catch(() => null);
    }

    // Members: one WF_TEAM role per member, carrying booking/member-management
    // permissions from their WF_AFFILIATE role. Main CIDs need no role row
    // (owners are covered by teamOwnerCids); members already on another team
    // stay there and are reported back instead of being moved.
    const mainCids = new Set(group.map(a => Number(a.cid)).filter(Boolean));
    const memberRows = await prisma.affiliateMember.findMany({
      where: { affiliateId: { in: group.map(a => a.id) } }
    }).catch(() => []);
    const seen = new Set();
    for (const m of memberRows) {
      const cid = Number(m.cid);
      if (!cid || seen.has(cid) || mainCids.has(cid)) continue;
      seen.add(cid);
      const existingRole = await prisma.userAdditionalRole.findUnique({
        where: { cid_role: { cid, role: 'WF_TEAM' } }
      }).catch(() => null);
      if (existingRole) {
        summary.membersSkipped.push(cid);
        continue;
      }
      const affRole = await prisma.userAdditionalRole.findUnique({
        where: { cid_role: { cid, role: 'WF_AFFILIATE' } }
      }).catch(() => null);
      await prisma.userAdditionalRole.create({
        data: {
          cid,
          role: 'WF_TEAM',
          teamName,
          canEditBookings: affRole ? !!affRole.canEditBookings : false,
          canManageMembers: affRole ? !!affRole.canManageMembers : false,
          participating: m.active !== false
        }
      });
      teamMemberCids.add(cid);
      summary.membersMoved++;
    }

    // Remove the affiliate side, then drop WF_AFFILIATE from anyone orphaned
    await prisma.affiliateMember.deleteMany({ where: { affiliateId: { in: group.map(a => a.id) } } }).catch(() => null);
    await prisma.affiliate.deleteMany({ where: { id: { in: group.map(a => a.id) } } }).catch(() => null);
    for (const cid of mainCids) await revokeAffiliateRoleIfOrphaned(cid);
    for (const m of memberRows) await revokeAffiliateRoleIfOrphaned(m.cid);

    await loadTeamMembers();
    await loadAffiliateOwners();

    if (group.some(a => a.participatingWf26)) {
      autoAssignTeamThenAffiliate({ reason: `affiliate ${id} promoted to team` }).catch(() => {});
    }

    console.log(`[PROMOTE] Affiliate "${teamName}" -> Official Team: ${summary.aircraft} aircraft, ${summary.membersMoved} member(s) moved, ${summary.membersSkipped.length} skipped, ${summary.optOuts} opt-out(s), ${summary.assignments} assignment(s)`);
    return res.json({ success: true, ...summary });
  } catch (e) {
    console.error('[PROMOTE] failed:', e);
    return res.status(500).json({ error: e.message || 'Promotion failed' });
  }
});


/* ===== CHANGE CHECK ===== */
app.get('/departures/check-changes', async (req, res) => {
  const icao = req.query.icao?.toUpperCase();
  if (!icao) return res.json({ changed: false });

  const response = await axios.get('https://data.vatsim.net/v3/vatsim-data.json');

  const currentSet = new Set(
    response.data.pilots
      .filter(p => p.flight_plan && p.flight_plan.departure === icao && p.groundspeed < 5)
      .map(p => `${p.callsign}-${p.flight_plan.arrival}`)
  );

  const changed = currentSet.size !== lastDepartureSnapshot.size;
  lastDepartureSnapshot = currentSet;

  res.json({ changed });
});

