/* ===== GREAT CIRCLE HELPER ===== */
function greatCircleArc(lat1, lon1, lat2, lon2, numPoints) {
  var toRad = Math.PI / 180;
  var toDeg = 180 / Math.PI;
  var f1 = lat1 * toRad, l1 = lon1 * toRad;
  var f2 = lat2 * toRad, l2 = lon2 * toRad;
  var d = 2 * Math.asin(Math.sqrt(
    Math.pow(Math.sin((f2 - f1) / 2), 2) +
    Math.cos(f1) * Math.cos(f2) * Math.pow(Math.sin((l2 - l1) / 2), 2)
  ));
  var points = [];
  for (var i = 0; i <= numPoints; i++) {
    var frac = i / numPoints;
    var a = Math.sin((1 - frac) * d) / Math.sin(d);
    var b = Math.sin(frac * d) / Math.sin(d);
    var x = a * Math.cos(f1) * Math.cos(l1) + b * Math.cos(f2) * Math.cos(l2);
    var y = a * Math.cos(f1) * Math.sin(l1) + b * Math.cos(f2) * Math.sin(l2);
    var z = a * Math.sin(f1) + b * Math.sin(f2);
    points.push([Math.atan2(z, Math.sqrt(x * x + y * y)) * toDeg, Math.atan2(y, x) * toDeg]);
  }
  return points;
}

/* ===== ROUTE PREVIEW MAP ===== */
(function() {
  var toInput = document.getElementById('addLegTo');
  var fromInput = document.getElementById('addLegFrom');
  var mapPanel = document.getElementById('addLegMapPanel');
  var dialog = document.getElementById('addLegDialog');

  var placeholder = document.getElementById('addLegMapPlaceholder');

  if (!toInput || !fromInput || !mapPanel) return;

  var legMap = null;
  var legMarkers = [];
  var legLine = null;
  var mapDebounce = null;

  function updateRouteMap() {
    clearTimeout(mapDebounce);
    var fromVal = (fromInput.value || '').trim().toUpperCase();
    var toVal = (toInput.value || '').trim().toUpperCase();

    if (!/^[A-Z]{4}$/.test(fromVal) || !/^[A-Z]{4}$/.test(toVal)) {
      if (placeholder) placeholder.style.display = '';
      return;
    }

    mapDebounce = setTimeout(async function() {
      try {
        var r1 = await fetch('/api/airport-coords/' + fromVal);
        var r2 = await fetch('/api/airport-coords/' + toVal);
        if (!r1.ok || !r2.ok) return;
        var fromAp = await r1.json();
        var toAp = await r2.json();

        if (placeholder) placeholder.style.display = 'none';

        if (!legMap) {
          legMap = L.map('addLegMap', { zoomControl: true, attributionControl: false, scrollWheelZoom: false, doubleClickZoom: false, boxZoom: false }).setView([0, 0], 2);
          wfAddTileLayer(legMap, { maxZoom: 18 });

          // Load FIR boundaries
          fetch('/api/fir-merged.geojson').then(function(r) { return r.json(); }).then(function(geojson) {
            var firLayer = L.geoJSON(geojson, {
              interactive: false,
              style: { color: '#334155', weight: 1, opacity: 0.4, fillColor: 'transparent', fillOpacity: 0 }
            }).addTo(legMap);

            // FIR name labels — show when zoomed in
            var firLabels = L.layerGroup();
            var seenLabels = {};
            geojson.features.forEach(function(f) {
              if (!f.properties?.id || !f.properties?.label_lat) return;
              var base = f.properties.id.split('-')[0];
              if (seenLabels[base]) return;
              seenLabels[base] = true;
              var label = L.marker(
                [parseFloat(f.properties.label_lat), parseFloat(f.properties.label_lon)],
                { icon: L.divIcon({
                  className: 'fir-label',
                  html: '<span>' + base + '</span>',
                  iconSize: [60, 16],
                  iconAnchor: [30, 8]
                })}
              );
              firLabels.addLayer(label);
            });

            function toggleFirLabels() {
              if (legMap.getZoom() >= 4) {
                if (!legMap.hasLayer(firLabels)) legMap.addLayer(firLabels);
              } else {
                if (legMap.hasLayer(firLabels)) legMap.removeLayer(firLabels);
              }
            }
            legMap.on('zoomend', toggleFirLabels);
            toggleFirLabels();

          }).catch(function() {});
        }

        setTimeout(function() { legMap.invalidateSize(); }, 350);

        legMarkers.forEach(function(m) { legMap.removeLayer(m); });
        legMarkers = [];
        if (legLine) { legMap.removeLayer(legLine); legLine = null; }

        var fromIcon = L.divIcon({ className: '', html: '<div style="background:#4ade80;width:10px;height:10px;border-radius:50%;border:2px solid #fff;"></div>', iconSize: [14, 14], iconAnchor: [7, 7] });
        var toIcon = L.divIcon({ className: '', html: '<div style="background:#38bdf8;width:10px;height:10px;border-radius:50%;border:2px solid #fff;"></div>', iconSize: [14, 14], iconAnchor: [7, 7] });

        var m1 = L.marker([fromAp.lat, fromAp.lon], { icon: fromIcon }).addTo(legMap);
        m1.bindTooltip('<strong>' + fromAp.icao + '</strong>', { className: 'map-suggest-tooltip', permanent: true, direction: 'top', offset: [0, -8] });

        var m2 = L.marker([toAp.lat, toAp.lon], { icon: toIcon }).addTo(legMap);
        m2.bindTooltip('<strong>' + toAp.icao + '</strong>', { className: 'map-suggest-tooltip', permanent: true, direction: 'top', offset: [0, -8] });

        legMarkers = [m1, m2];

        // Read route from the Add Leg modal textarea
        var routeTextarea = document.getElementById('addLegRoute');
        var routeStr = routeTextarea ? routeTextarea.value.trim() : '';

        if (routeStr) {
          // Resolve route via API
          var depTimeEl = document.getElementById('addLegDepTime');
          var depTimeVal = depTimeEl ? depTimeEl.value.replace(' UTC', '').trim() : '';
          var blockTimeVal = document.getElementById('addLegSimbriefFetch')?.dataset?.blockTime || '';

          fetch('/api/resolve-route?from=' + fromVal + '&to=' + toVal + '&route=' + encodeURIComponent(routeStr) + '&depTime=' + encodeURIComponent(depTimeVal) + '&blockTime=' + encodeURIComponent(blockTimeVal))
            .then(function(r) { return r.json(); })
            .then(function(data) {
              if (data.points && data.points.length >= 2) {
                var routeCoords = data.points.map(function(p) { return [p.lat, p.lon]; });

                // Draw resolved route as solid line
                var routeLine = L.polyline(routeCoords, { color: '#f59e0b', weight: 2.5, opacity: 0.9 }).addTo(legMap);
                legMarkers.push(routeLine);

                // Add small dots for each waypoint
                data.points.forEach(function(p, i) {
                  if (i === 0 || i === data.points.length - 1) return;
                  var wpIcon = L.divIcon({ className: '', html: '<div style="background:#f59e0b;width:4px;height:4px;border-radius:50%;"></div>', iconSize: [4, 4], iconAnchor: [2, 2] });
                  var wpM = L.marker([p.lat, p.lon], { icon: wpIcon }).addTo(legMap);
                  wpM.bindTooltip(p.name, { className: 'map-suggest-tooltip' });
                  legMarkers.push(wpM);
                });

                legMap.fitBounds(routeLine.getBounds(), { padding: [20, 20], animate: false });
              }

            }).catch(function() {});
        }

        // Great circle arc (always shown as dashed reference)
        var gcPoints = greatCircleArc(fromAp.lat, fromAp.lon, toAp.lat, toAp.lon, 80);
        legLine = L.polyline(gcPoints, {
          color: '#38bdf8', weight: 1.5, opacity: 0.3, dashArray: '4,6'
        }).addTo(legMap);

        legMap.fitBounds(legLine.getBounds(), { padding: [20, 20], animate: false });

      } catch(err) { console.error('[ROUTE MAP ERROR]', err); }
    }, 400);
  }

  toInput.addEventListener('input', updateRouteMap);
  toInput.addEventListener('change', updateRouteMap);

  var routeTextarea = document.getElementById('addLegRoute');
  if (routeTextarea) {
    var routeDebounce = null;
    routeTextarea.addEventListener('input', function() {
      routeTextarea.style.height = 'auto';
      routeTextarea.style.height = routeTextarea.scrollHeight + 'px';
      clearTimeout(routeDebounce);
      routeDebounce = setTimeout(updateRouteMap, 600);
    });
  }
})();

/* ===== ADD LEG SIMBRIEF ===== */
(function() {
  var genBtn = document.getElementById('addLegSimbriefGen');
  var fetchBtn = document.getElementById('addLegSimbriefFetch');
  var msgEl = document.getElementById('addLegSimbriefMsg');
  var routeTextarea = document.getElementById('addLegRoute');
  var fromInput = document.getElementById('addLegFrom');
  var toInput = document.getElementById('addLegTo');

  if (!genBtn || !fetchBtn) return;

  genBtn.addEventListener('click', function() {
    var from = (fromInput.value || '').trim().toUpperCase();
    var to = (toInput.value || '').trim().toUpperCase();
    var route = (routeTextarea.value || '').trim();

    if (!from || !to) { alert('Enter From and To first.'); return; }

    var pilotId = (document.getElementById('simbriefPilotId')?.value || '').trim();

    var cfg = window.WF_EVENT_CONFIG || {};
    var acType = cfg.aircraftType || 'B738';
    var isNonWf = cfg.isWorldFlight === false;
    var mode = isNonWf ? (cfg.cruiseMode || 'CI') : null;
    var cruise = isNonWf ? mode : (acType === 'B744' ? 'M85' : acType === 'B77W' ? 'M84' : 'M78');
    var forcedFl = isNonWf && cfg.cruiseAltitude && cfg.cruiseAltitude > 0 ? cfg.cruiseAltitude : 0;
    var url = 'https://dispatch.simbrief.com/options/custom'
      + '?orig=' + encodeURIComponent(from)
      + '&dest=' + encodeURIComponent(to)
      + (route ? '&route=' + encodeURIComponent(route) : '')
      + '&type=' + acType
      + '&cruise=' + cruise
      + (isNonWf ? '&civalue=' + (cfg.costIndex ?? 30) : '')
      + (forcedFl ? '&fl=' + forcedFl : '')
      + '&manualrmk=' + encodeURIComponent('WorldFlight Validated Route - www.planning.worldflight.center');

    window.open(url, 'simbrief', 'width=1100,height=750,scrollbars=yes,resizable=yes');

    // Enable fetch button
    fetchBtn.disabled = false;
    fetchBtn.style.background = 'var(--success)';
    fetchBtn.style.color = '#020617';
    fetchBtn.style.fontWeight = '600';
    msgEl.textContent = 'Generate your plan in SimBrief, then click Pull SimBrief Data.';
    msgEl.style.display = '';
    msgEl.style.color = 'var(--accent)';
  });

  fetchBtn.addEventListener('click', async function() {
    var pilotId = (document.getElementById('simbriefPilotId')?.value || '').trim();
    if (!pilotId) { alert('Enter your SimBrief Pilot ID first.'); return; }

    var from = (fromInput.value || '').trim().toUpperCase();
    var to = (toInput.value || '').trim().toUpperCase();

    fetchBtn.disabled = true;
    fetchBtn.textContent = 'Fetching...';
    msgEl.textContent = 'Fetching from SimBrief...';
    msgEl.style.color = 'var(--accent)';

    try {
      var res = await fetch('https://www.simbrief.com/api/xml.fetcher.php?userid=' + encodeURIComponent(pilotId) + '&json=1');
      var data = await res.json();

      if (!data || !data.times) throw new Error('No flight plan found');

      var ofpOrig = (data.origin?.icao_code || '').toUpperCase();
      var ofpDest = (data.destination?.icao_code || '').toUpperCase();

      if (ofpOrig !== from || ofpDest !== to) {
        msgEl.textContent = 'Latest plan is ' + ofpOrig + ' → ' + ofpDest + ', expected ' + from + ' → ' + to + '. Generate the correct plan first.';
        msgEl.style.color = 'var(--danger)';
        fetchBtn.disabled = false;
        fetchBtn.textContent = 'Pull SimBrief Data';
        return;
      }

      // Extract route and block time
      var ofpRoute = data.general?.route || '';
      var blockSecs = Number(data.times?.sched_block) || Number(data.times?.est_block) || 0;
      var blockHrs = Math.floor(blockSecs / 3600);
      var blockMins = Math.floor((blockSecs % 3600) / 60);
      var blockStr = String(blockHrs).padStart(2, '0') + ':' + String(blockMins).padStart(2, '0');
      var flightSecs = Number(data.times?.est_time_enroute) || 0;
      var flightHrs = Math.floor(flightSecs / 3600);
      var flightMinsOut = Math.floor((flightSecs % 3600) / 60);
      var flightStr = flightSecs ? (String(flightHrs).padStart(2, '0') + ':' + String(flightMinsOut).padStart(2, '0')) : '';

      // Fill in route
      if (ofpRoute) {
        routeTextarea.value = ofpRoute;
        routeTextarea.dispatchEvent(new Event('input'));
      }

      msgEl.innerHTML = 'Route, block (' + blockStr + ')' + (flightStr ? ', flight (' + flightStr + ')' : '') + ' loaded from SimBrief.';
      msgEl.style.color = 'var(--success)';

      // Store times for when we submit
      fetchBtn.dataset.blockTime = blockStr;
      fetchBtn.dataset.flightTime = flightStr;
      fetchBtn.textContent = 'Pull SimBrief Data';
      fetchBtn.disabled = true;

      // Now fetch FIR transit data with block time available
      var depTimeEl = document.getElementById('addLegDepTime');
      var depTimeVal = depTimeEl ? depTimeEl.value.replace(' UTC', '').trim() : '';
      var firSection = document.getElementById('addLegFirSection');

      if (from && to && ofpRoute && depTimeVal && blockStr) {
        fetch('/api/resolve-route?from=' + encodeURIComponent(from) + '&to=' + encodeURIComponent(to) + '&route=' + encodeURIComponent(ofpRoute) + '&depTime=' + encodeURIComponent(depTimeVal) + '&blockTime=' + encodeURIComponent(blockStr))
          .then(function(r) { return r.json(); })
          .then(function(data) {
            if (data.firs && data.firs.length && firSection) {
              firSection.style.display = 'block';
              var firList = document.getElementById('addLegFirList');
              firList.innerHTML = data.firs.map(function(f) {
                var label = /^K[A-Z]{3}$/.test(f.fir) ? f.fir.slice(1) : f.fir;
                if (f.staffStart && f.staffEnd) {
                  label += ' <span class="fir-time">' + f.staffStart + ' – ' + f.staffEnd + '</span>';
                }
                return '<span class="fir-tag">' + label + '</span>';
              }).join('');
            }
          }).catch(function() {});
      }

    } catch(err) {
      msgEl.textContent = 'Failed: ' + err.message;
      msgEl.style.color = 'var(--danger)';
      fetchBtn.disabled = false;
      fetchBtn.textContent = 'Pull SimBrief Data';
    }
  });
})();

/* ===== SIMBRIEF PILOT ID (persist in localStorage) ===== */
(function() {
  var pidInput = document.getElementById('simbriefPilotId');
  if (!pidInput) return;
  pidInput.value = localStorage.getItem('simbriefPilotId') || '52776';
  pidInput.addEventListener('change', function() {
    localStorage.setItem('simbriefPilotId', pidInput.value.trim());
  });
})();

/* ===== EVENT FLIGHT CONFIG (WorldFlight toggle / suffix / a/c type) ===== */
(function() {
  var chk = document.getElementById('isWorldFlightChk');
  if (!chk) return;
  var cfgBox = document.getElementById('nonWfConfig');
  var suffixInput = document.getElementById('flightSuffixInput');
  var acSelect = document.getElementById('aircraftTypeSelect');
  var startInput = document.getElementById('flightStartInput');
  var prefixLabel = document.getElementById('flightPrefixLabel');
  var ciInput = document.getElementById('costIndexInput');

  function save(payload) {
    fetch('/admin/api/wf-events/' + window.WF_EVENT_ID + '/flight-config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }).then(function(r) {
      if (r.ok) {
        Object.assign(window.WF_EVENT_CONFIG, payload);
        if (payload.flightSuffix !== undefined) {
          payload.flightSuffix = payload.flightSuffix.toUpperCase().trim();
          window.WF_EVENT_CONFIG.flightSuffix = payload.flightSuffix;
        }
      }
    });
  }

  chk.addEventListener('change', function() {
    cfgBox.style.display = chk.checked ? 'none' : 'flex';
    // WF Challenge only applies to WorldFlight events — hide and clear it otherwise
    var challengeBox = document.getElementById('wfChallengeBox');
    if (challengeBox) {
      challengeBox.style.display = chk.checked ? 'flex' : 'none';
      var cChk = document.getElementById('wfChallengeChk');
      if (!chk.checked && cChk && cChk.checked) {
        cChk.checked = false;
        document.getElementById('wfChallengeSelect').style.display = 'none';
        fetch('/admin/api/schedule/wf-challenge', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ eventId: window.WF_EVENT_ID, number: '' })
        });
      }
    }
    save({ isWorldFlight: chk.checked });
    var fromInput = document.getElementById('addLegFrom');
    var prevSel = document.getElementById('addLegPrev');
    if (fromInput && prevSel && prevSel.value === 'START') {
      fromInput.value = chk.checked ? 'YSSY' : '';
    }
  });

  if (suffixInput) {
    suffixInput.addEventListener('input', function() {
      if (prefixLabel) prefixLabel.textContent = (suffixInput.value || '').toUpperCase().trim() || 'BA';
    });
    suffixInput.addEventListener('change', function() {
      save({ flightSuffix: suffixInput.value });
    });
  }
  if (startInput) {
    startInput.addEventListener('change', function() {
      var n = Number(startInput.value);
      if (!Number.isFinite(n) || n < 0) return;
      save({ flightStartNumber: Math.floor(n) });
    });
  }
  if (acSelect) {
    acSelect.addEventListener('change', function() {
      save({ aircraftType: acSelect.value });
    });
  }
  var cruiseModeSelect = document.getElementById('cruiseModeSelect');
  function applyCruiseModeBounds(mode) {
    if (!ciInput) return;
    if (mode === 'KIAS') {
      ciInput.min = '100'; ciInput.max = '350'; ciInput.title = 'KIAS — indicated airspeed in knots (100-350)';
    } else if (mode === 'MACH') {
      ciInput.min = '50'; ciInput.max = '99'; ciInput.title = 'Mach — enter tens digit(s), e.g. 78 for M0.78';
    } else {
      ciInput.min = '0'; ciInput.max = '999'; ciInput.title = 'Cost Index (0-999)';
    }
  }
  applyCruiseModeBounds((window.WF_EVENT_CONFIG && window.WF_EVENT_CONFIG.cruiseMode) || 'CI');
  if (cruiseModeSelect) {
    cruiseModeSelect.addEventListener('change', function() {
      applyCruiseModeBounds(cruiseModeSelect.value);
      save({ cruiseMode: cruiseModeSelect.value });
    });
  }
  if (ciInput) {
    ciInput.addEventListener('change', function() {
      var n = Number(ciInput.value);
      if (!Number.isFinite(n) || n < 0 || n > 999) return;
      save({ costIndex: Math.floor(n) });
    });
  }
  var nsaSelect = document.getElementById('nextSectorAfterSelect');
  if (nsaSelect) {
    nsaSelect.addEventListener('change', function() {
      saveStartAndReload({ nextSectorAfter: nsaSelect.value });
    });
  }
  var flInput = document.getElementById('cruiseAltitudeInput');
  if (flInput) {
    flInput.addEventListener('change', function() {
      var raw = flInput.value.trim();
      var n = raw === '' ? 0 : Number(raw);
      if (!Number.isFinite(n) || n < 0 || n > 600) return;
      save({ cruiseAltitude: Math.floor(n) });
    });
  }

  var startDateEl = document.getElementById('eventStartDateInput');
  var startTimeEl = document.getElementById('eventStartTimeInput');
  var startDateBtn = document.getElementById('eventStartDateBtn');
  var startDateLabel = document.getElementById('eventStartDateLabel');

  function formatDisplayDate(iso) {
    if (!iso || !/^\d{4}-\d{2}-\d{2}$/.test(iso)) return 'Pick date';
    var parts = iso.split('-');
    var d = new Date(Date.UTC(+parts[0], +parts[1] - 1, +parts[2]));
    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    var day = d.getUTCDate();
    var suf = day === 1 || day === 21 || day === 31 ? 'st'
      : day === 2 || day === 22 ? 'nd'
      : day === 3 || day === 23 ? 'rd' : 'th';
    return days[d.getUTCDay()] + ' ' + day + suf + ' ' + months[d.getUTCMonth()] + ' ' + d.getUTCFullYear();
  }
  if (startDateLabel) startDateLabel.textContent = formatDisplayDate(startDateEl ? startDateEl.value : '');

  var dpModal = document.getElementById('datePickerModal');
  var dpGrid = document.getElementById('dpGrid');
  var dpMonthYear = document.getElementById('dpMonthYear');
  var dpViewYear, dpViewMonth;

  function pad2(n) { return String(n).padStart(2, '0'); }
  function toIso(y, m, d) { return y + '-' + pad2(m + 1) + '-' + pad2(d); }

  function renderDp() {
    var monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    dpMonthYear.textContent = monthNames[dpViewMonth] + ' ' + dpViewYear;

    var firstOfMonth = new Date(Date.UTC(dpViewYear, dpViewMonth, 1));
    var firstWeekday = (firstOfMonth.getUTCDay() + 6) % 7; // Monday = 0
    var daysInMonth = new Date(Date.UTC(dpViewYear, dpViewMonth + 1, 0)).getUTCDate();
    var daysInPrev = new Date(Date.UTC(dpViewYear, dpViewMonth, 0)).getUTCDate();

    var today = new Date();
    var todayIso = toIso(today.getFullYear(), today.getMonth(), today.getDate());
    var selectedIso = startDateEl ? startDateEl.value : '';

    dpGrid.innerHTML = '';
    var totalCells = 42;
    for (var i = 0; i < totalCells; i++) {
      var dayNum, cellMonth, cellYear, isOther;
      if (i < firstWeekday) {
        dayNum = daysInPrev - firstWeekday + 1 + i;
        cellMonth = dpViewMonth === 0 ? 11 : dpViewMonth - 1;
        cellYear = dpViewMonth === 0 ? dpViewYear - 1 : dpViewYear;
        isOther = true;
      } else if (i < firstWeekday + daysInMonth) {
        dayNum = i - firstWeekday + 1;
        cellMonth = dpViewMonth;
        cellYear = dpViewYear;
        isOther = false;
      } else {
        dayNum = i - firstWeekday - daysInMonth + 1;
        cellMonth = dpViewMonth === 11 ? 0 : dpViewMonth + 1;
        cellYear = dpViewMonth === 11 ? dpViewYear + 1 : dpViewYear;
        isOther = true;
      }
      var iso = toIso(cellYear, cellMonth, dayNum);
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'dp-day' + (isOther ? ' dp-other-month' : '') + (iso === todayIso ? ' dp-today' : '') + (iso === selectedIso ? ' dp-selected' : '');
      btn.textContent = dayNum;
      btn.dataset.iso = iso;
      btn.addEventListener('click', function() {
        var picked = this.dataset.iso;
        startDateEl.value = picked;
        startDateLabel.textContent = formatDisplayDate(picked);
        dpModal.classList.add('hidden');
        saveStartAndReload({ startDateUtc: picked });
      });
      dpGrid.appendChild(btn);
    }
  }

  function openDp() {
    var current = startDateEl && startDateEl.value;
    var base;
    if (current && /^\d{4}-\d{2}-\d{2}$/.test(current)) {
      var p = current.split('-');
      base = new Date(Date.UTC(+p[0], +p[1] - 1, +p[2]));
    } else {
      base = new Date();
    }
    dpViewYear = base.getUTCFullYear ? base.getUTCFullYear() : base.getFullYear();
    dpViewMonth = base.getUTCMonth ? base.getUTCMonth() : base.getMonth();
    renderDp();
    dpModal.classList.remove('hidden');
  }

  if (startDateBtn) startDateBtn.addEventListener('click', openDp);
  if (dpModal) {
    dpModal.querySelector('.modal-backdrop').addEventListener('click', function() {
      dpModal.classList.add('hidden');
    });
    document.getElementById('dpPrev').addEventListener('click', function() {
      dpViewMonth--;
      if (dpViewMonth < 0) { dpViewMonth = 11; dpViewYear--; }
      renderDp();
    });
    document.getElementById('dpNext').addEventListener('click', function() {
      dpViewMonth++;
      if (dpViewMonth > 11) { dpViewMonth = 0; dpViewYear++; }
      renderDp();
    });
    document.getElementById('dpMonthYear').addEventListener('click', function() {
      var t = new Date();
      dpViewYear = t.getFullYear();
      dpViewMonth = t.getMonth();
      renderDp();
    });
    document.getElementById('dpToday').addEventListener('click', function() {
      var t = new Date();
      var iso = toIso(t.getFullYear(), t.getMonth(), t.getDate());
      startDateEl.value = iso;
      startDateLabel.textContent = formatDisplayDate(iso);
      dpModal.classList.add('hidden');
      saveStartAndReload({ startDateUtc: iso });
    });
    document.getElementById('dpClear').addEventListener('click', function() {
      startDateEl.value = '';
      startDateLabel.textContent = 'Pick date';
      dpModal.classList.add('hidden');
      saveStartAndReload({ startDateUtc: '' });
    });
    document.getElementById('dpClose').addEventListener('click', function() {
      dpModal.classList.add('hidden');
    });
  }

  function saveStartAndReload(payload) {
    var overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(2,6,23,0.9);display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:9999;';
    overlay.innerHTML = '<div style="text-align:center;">' +
      '<div style="width:36px;height:36px;border:3px solid rgba(255,255,255,0.1);border-top-color:var(--accent,#38bdf8);border-radius:50%;animation:spin .8s linear infinite;margin:0 auto 16px;"></div>' +
      '<h2 style="color:var(--text,#e5e7eb);font-size:18px;margin:0 0 6px;">Recalculating...</h2>' +
      '<p style="color:var(--muted,#94a3b8);font-size:13px;">Applying new start date/time</p>' +
      '</div><style>@keyframes spin{to{transform:rotate(360deg)}}</style>';
    document.body.appendChild(overlay);
    fetch('/admin/api/wf-events/' + window.WF_EVENT_ID + '/flight-config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }).then(function(r) {
      if (r.ok) location.reload();
      else {
        document.body.removeChild(overlay);
        alert('Failed to save start date/time.');
      }
    });
  }
  if (startTimeEl) {
    startTimeEl.addEventListener('change', function() {
      saveStartAndReload({ startTimeUtc: startTimeEl.value });
    });
  }
})();

/* ===== SECTOR OVERVIEW ===== */
