/* ===== LOGOUT ===== */
app.get('/logout', (req, res) => {
  req.session.destroy(err => {
    if (err) {
      console.error('Logout error:', err);
      return res.status(500).send('Logout failed');
    }

    res.clearCookie('worldflight.sid', {
      path: '/',
      httpOnly: true,
      sameSite: 'lax'
    });

    return res.redirect('/');
  });
});


